values ('msq_lv5_class_intro', 'Your First Calling', 'tutorial', 'D', 'NONE', 'NEXUS_CORE', 'You have reached Level 5. Your potential has crystallized into something the factions recognize. Seek your faction''s Class Trainer and choose your base class specialization.', '{"npc_id": "npc_class_advisor", "name": "Guide Axiom", "location": "Nexus Core"}'::jsonb, '{"min_level": 5, "reputation_required": 0, "required_quests": []}'::jsonb, '[{"type": "interact", "target": "npc_class_advisor", "count": 1, "description": "Speak with Guide Axiom, the Class Advisor, in Nexus Core."}]'::jsonb, '{"exp": 250, "currency": 100, "crd": 50, "reputation": 50, "items": [{"item_id": "con_small_hp_cell", "quantity": 3}, {"item_id": "echo_memory_core_low", "quantity": 1}, {"item_id": "recomendation_letters", "quantity": 1}]}'::jsonb, false, false, NULL, true, 'on_level_up', 5, NULL, 'quest_list.json', 0)
