values ('msq_lv20_advanced_reminder', 'The Next Threshold', 'tutorial', 'C', 'NONE', 'NEXUS_CORE', 'Level 20 — the Advanced class threshold. Return to your faction''s Class Trainer. Prove yourself in combat to unlock your Advanced specialization branch.', '{"npc_id": "npc_class_advisor", "name": "Guide Axiom", "location": "Nexus Core"}'::jsonb, '{"min_level": 20, "reputation_required": 0, "required_quests": []}'::jsonb, '[{"type": "interact", "target": "class_trainer", "count": 1, "description": "Return to your faction''s Class Trainer to begin the Advanced trial."}]'::jsonb, '{"exp": 1500, "currency": 500, "crd": 200, "reputation": 100, "items": [{"item_id": "advanced_hp_potion", "quantity": 3}]}'::jsonb, false, false, NULL, true, 'on_level_up', 20, NULL, 'quest_list.json', 1)
