values ('msq_lv40_master_reminder', 'The Ascension', 'tutorial', 'B', 'NONE', 'NEXUS_CORE', 'Level 40 — the Ascension. The Master class tier is now within reach. Seek your faction''s trainer and complete the Ascension trial to claim your Master designation.', '{"npc_id": "npc_class_advisor", "name": "Guide Axiom", "location": "Nexus Core"}'::jsonb, '{"min_level": 40, "reputation_required": 0, "required_quests": []}'::jsonb, '[{"type": "interact", "target": "class_trainer", "count": 1, "description": "Seek your faction''s Class Trainer for the Ascension trial."}]'::jsonb, '{"exp": 8000, "currency": 2000, "crd": 1000, "reputation": 500, "items": [{"item_id": "legendary_cache", "quantity": 1}]}'::jsonb, false, false, NULL, true, 'on_level_up', 40, NULL, 'quest_list.json', 2)
