values ('fq_arc_001', 'First Specimen, First Sin', 'story', 'D', 'THE_ARCANUM_SEEKERS', 'CRYSTAL_SLOPE', 'High Seeker Elara Voss has inducted you into the Arcanum Seekers — the faction the Concordium calls reckless and the Iron Hegemony calls dangerous, and who call themselves the only people on Xylos who are asking the right questions. The Crystal Slope''s Wild Mushrooms absorb raw aethel from the Shard fragment impact site nearby, storing energy signatures that predate the Great Severance. The Arcanum needs those signatures. Knowledge has a price, and it begins here. Quest giver: Scholar Elara at Observatory Spire Research Wing.', '{"npc_id": "npc_arcanum_scholar", "name": "High Seeker Elara Voss", "location": "CRYSTAL_SLOPE"}'::jsonb, '{"min_level": 1, "reputation_required": 0, "required_quests": []}'::jsonb, '[{"type": "kill", "target": "WILD_MUSHROOM", "count": 4, "description": "Defeat Wild Mushrooms and extract their mystic energy."}, {"type": "collect", "target": "mushroom_cap", "count": 2, "description": "Collect mushroom cap (x2). [Item: Mushroom Cap]"}]'::jsonb, '{"exp": 50, "currency": 30, "crd": 0, "rep": 30, "items": [{"item_id": "con_small_hp_cell", "quantity": 3}, {"item_id": "con_small_mp_cell", "quantity": 2}], "reputation": 5}'::jsonb, false, false, 'fq_arc_002', false, NULL, NULL, NULL, 'quest_arcanum.json', 0)
