values ('fq_arc_003', 'The Living Archive', 'story', 'D', 'THE_ARCANUM_SEEKERS', 'CRYSTAL_SLOPE', 'Archivist Sylas — the Arcanum''s keeper of specimens and secrets — has a theory: Shardlings are not random creatures but fractal echoes of the original Aethel Shard, each one containing a tiny portion of the Shard''s encoded memory. (Location: Crystal Slope, Archivist Sylas) The Concordium wants to regulate the Shard. The Arcanum wants to read it. Bring Sylas enough Shardlings and he will begin to translate what the Shard is trying to say.', '{"npc_id": "npc_arcanum_archivist", "name": "Archivist Sylas", "location": "CRYSTAL_SLOPE"}'::jsonb, '{"min_level": 2, "reputation_required": 10, "required_quests": ["fq_arc_002"]}'::jsonb, '[{"type": "kill", "target": "SHARDLING", "count": 5, "description": "Capture Shardling fragments for the archive."}, {"type": "collect", "target": "crystal_fragment", "count": 3, "description": "Collect crystal fragment (x3). [Item: Crystal Fragment]"}]'::jsonb, '{"exp": 70, "currency": 40, "crd": 0, "rep": 40, "items": [{"item_id": "void_crystal_shard", "quantity": 1}], "reputation": 5}'::jsonb, false, false, 'fq_arc_004', false, NULL, NULL, NULL, 'quest_arcanum.json', 2)
