values ('fq_arc_005', 'The Spire Calls to You', 'tutorial', 'D', 'THE_ARCANUM_SEEKERS', 'OBSERVATORY_SPIRE', 'The Observatory Spire is the Arcanum''s crown jewel — a tower built to watch the stars and read the aethel currents that flow between them. Archsage Myr has reviewed your field reports and called you to the Spire in person. In the Arcanum, knowledge specialization is not a promotion; it is a philosophical declaration of what questions you will spend your life pursuing. Choose carefully. The wrong answer will not be punished — but it will define you.', '{"npc_id": "npc_arcanum_class_trainer", "name": "Archsage Myr", "location": "OBSERVATORY_SPIRE"}'::jsonb, '{"min_level": 4, "reputation_required": 20, "required_quests": ["fq_arc_004"], "required_items": ["recomendation_letters"]}'::jsonb, '[{"type": "interact", "target": "npc_arcanum_class_trainer", "count": 1, "description": "Speak with Archsage Myr at the Observatory Spire. (Archsage Myr at Observatory Spire Academy)"}, {"type": "interact", "target": "class_change_screen", "count": 1, "description": "Open the class selection screen."}, {"type": "kill", "target": "WILD_MUSHROOM", "count": 3, "description": "Demonstrate your arcane potential against Wild Mushrooms."}]'::jsonb, '{"exp": 400, "currency": 200, "crd": 0, "rep": 150, "items": [{"item_id": "wpn_apprentice_staff", "quantity": 1}, {"item_id": "armor_cloth_robes", "quantity": 1}, {"item_id": "rare_emblem", "quantity": 1}, {"item_id": "echo_memory_core_low", "quantity": 1}], "reputation": 5}'::jsonb, false, false, 'fq_arc_006', true, 'on_quest_complete', 4, 'fq_arc_004', 'quest_arcanum.json', 4)
