values ('fq_arc_006', 'The Shattered Laboratory', 'story', 'D', 'THE_ARCANUM_SEEKERS', 'FRACTURED_GLASS_VALLEY', 'The Fractured Glass Valley was an Aethelgardian research station before the Severance shattered it — and the terrain along with it. High Seeker Elara Voss has been trying to get a team in here for years, but the Concordium kept classifying it restricted. Now, post-Schism, in the chaos of competing factions, the Arcanum moves. The data slates buried in the glass are worth more than the annual budget of most research divisions. Get in before anyone else does. Quest giver: Scholar Elara at Observatory Spire Research Wing.', '{"npc_id": "npc_arcanum_scholar", "name": "High Seeker Elara Voss", "location": "FRACTURED_GLASS_VALLEY"}'::jsonb, '{"min_level": 5, "reputation_required": 20, "required_quests": ["fq_arc_005"]}'::jsonb, '[{"type": "travel", "target": "FRACTURED_GLASS_VALLEY", "count": 1, "description": "Enter the Fractured Glass Valley."}, {"type": "collect", "target": "stinger_core", "count": 2, "description": "Collect stinger core (x2). [Item: Stinger Core]"}]'::jsonb, '{"exp": 100, "currency": 60, "crd": 0, "rep": 60, "items": [{"item_id": "con_minor_stim_pack", "quantity": 2}], "reputation": 5}'::jsonb, false, false, 'fq_arc_007', false, NULL, NULL, NULL, 'quest_arcanum.json', 5)
