insert into public.quests (id, title, type, rank, faction, region, description, quest_giver, requirements, objectives, rewards, repeatable, daily, quest_chain_next, popup, popup_trigger, popup_level, popup_prerequisite, source_file, sort_order)
values ('fq_arc_012', 'Interference Pattern', 'story', 'C', 'THE_ARCANUM_SEEKERS', 'RESONANCE_CAVERNS', 'Resonance Bats have adapted to use the caverns'' Aethelgardian frequency emissions as their primary navigation signal — which means when they pulse their own echolocation, it creates harmonic interference that drowns out the original signal the Arcanum is trying to record. (Location: Resonance Caverns, Researcher Vin) Researcher Vin is philosophical about it: ''They evolved into the frequency stream like we evolved into language.'' He still needs them neutralized before the interference destroys another month of data collection.', '{"npc_id": "npc_researcher_vin", "name": "Researcher Vin", "location": "RESONANCE_CAVERNS"}'::jsonb, '{"min_level": 11, "reputation_required": 50, "required_quests": ["fq_arc_011"]}'::jsonb, '[{"type": "kill", "target": "RESONANCE_BAT", "count": 6, "description": "Defeat Resonance Bats in the caverns."}, {"type": "collect", "target": "void_fragment", "count": 3, "description": "Collect void fragment (x3). [Item: Void Fragment]"}]'::jsonb, '{"exp": 320, "currency": 170, "crd": 0, "rep": 170, "items": [{"item_id": "brainwave_oscillator", "quantity": 1}], "reputation": 5}'::jsonb, false, false, 'fq_arc_013', false, NULL, NULL, NULL, 'quest_arcanum.json', 11)
