insert into public.quests (id, title, type, rank, faction, region, description, quest_giver, requirements, objectives, rewards, repeatable, daily, quest_chain_next, popup, popup_trigger, popup_level, popup_prerequisite, source_file, sort_order)
values ('fq_arc_013', 'Guardians of a Forgotten Archive', 'story', 'C', 'THE_ARCANUM_SEEKERS', 'RESONANCE_CAVERNS', 'Resonance Golems were not born — they were built, by Aethelgardian architects who understood acoustics as a force as real as gravity. (Location: Resonance Caverns, Scholar Elara) They still guard the cavern''s deeper chambers, still following protocols written before Xylos had a recorded history. High Seeker Elara Voss reads the technical specifications in their construction with open hunger: ''They solved in stone what we have not solved in silicon.'' She needs them disabled — and every component catalogued.', '{"npc_id": "npc_arcanum_scholar", "name": "High Seeker Elara Voss", "location": "RESONANCE_CAVERNS"}'::jsonb, '{"min_level": 12, "reputation_required": 55, "required_quests": ["fq_arc_012"]}'::jsonb, '[{"type": "kill", "target": "RESONANCE_GOLEM", "count": 2, "description": "Disable Resonance Golems for study."}, {"type": "collect", "target": "crystal_core", "count": 1, "description": "Collect crystal core (x1). [Item: Crystal Core]"}]'::jsonb, '{"exp": 450, "currency": 240, "crd": 0, "rep": 240, "items": [{"item_id": "cognitive_relay_node", "quantity": 1}], "reputation": 5}'::jsonb, false, false, 'fq_arc_014', false, NULL, NULL, NULL, 'quest_arcanum.json', 12)
