insert into public.quests (id, title, type, rank, faction, region, description, quest_giver, requirements, objectives, rewards, repeatable, daily, quest_chain_next, popup, popup_trigger, popup_level, popup_prerequisite, source_file, sort_order)
values ('fq_arc_014', 'The Proof in the Stone', 'story', 'C', 'THE_ARCANUM_SEEKERS', 'RESONANCE_CAVERNS', 'Archivist Sylas has mapped the echo patterns in the deepest cavern chambers and believes they form a recursive mathematical structure — a proof, encoded in reflected sound, that describes the fundamental resonance equation underlying aethel energy transfer. (Location: Resonance Caverns, Archivist Sylas) If he is right, this single proof is worth more than the entire Concordium''s engineering database. The Bats that keep disrupting his recordings have earned a very specific kind of contempt from a very quiet man.', '{"npc_id": "npc_arcanum_archivist", "name": "Archivist Sylas", "location": "RESONANCE_CAVERNS"}'::jsonb, '{"min_level": 13, "reputation_required": 60, "required_quests": ["fq_arc_013"]}'::jsonb, '[{"type": "kill", "target": "RESONANCE_BAT", "count": 5, "description": "Clear Bats from the echo chambers. [Resonance Bat]"}, {"type": "collect", "target": "void_fragment", "count": 2, "description": "Collect void fragment (x2). [Item: Void Fragment]"}]'::jsonb, '{"exp": 380, "currency": 200, "crd": 0, "rep": 200, "items": [{"item_id": "memory_fragment_chip", "quantity": 2}], "reputation": 5}'::jsonb, false, false, 'fq_arc_015', false, NULL, NULL, NULL, 'quest_arcanum.json', 13)
