values ('fq_arc_015', 'What the Signal Hides', 'story', 'C', 'THE_ARCANUM_SEEKERS', 'RESONANCE_CAVERNS', 'Something is actively corrupting the Aethelgardian signal in the Resonance Caverns — not random interference, but a structured counter-harmonic that High Seeker Elara Voss describes as deliberate suppression. Something in the deep chambers does not want the signal heard. The Golems are amplifying the suppression, and the Bats are spreading it. Elara''s eyes are bright with exactly the kind of dangerous curiosity that made the Concordium classify her research six times. Quest giver: Scholar Elara at Observatory Spire Research Wing.', '{"npc_id": "npc_arcanum_scholar", "name": "High Seeker Elara Voss", "location": "RESONANCE_CAVERNS"}'::jsonb, '{"min_level": 14, "reputation_required": 65, "required_quests": ["fq_arc_014"]}'::jsonb, '[{"type": "kill", "target": "RESONANCE_GOLEM", "count": 3, "description": "Destroy Golems causing harmonic interference. [Resonance Golem]"}, {"type": "kill", "target": "RESONANCE_BAT", "count": 5, "description": "Eliminate Bat swarms amplifying the interference. [Resonance Bat]"}]'::jsonb, '{"exp": 500, "currency": 280, "crd": 0, "rep": 300, "items": [{"item_id": "core_fragment", "quantity": 2}], "reputation": 5}'::jsonb, false, false, 'fq_arc_016', false, NULL, NULL, NULL, 'quest_arcanum.json', 14)
