insert into public.quests (id, title, type, rank, faction, region, description, quest_giver, requirements, objectives, rewards, repeatable, daily, quest_chain_next, popup, popup_trigger, popup_level, popup_prerequisite, source_file, sort_order)
values ('fq_arc_016', 'The Unmapped Chambers', 'story', 'C', 'THE_ARCANUM_SEEKERS', 'RESONANCE_CAVERNS', 'Archivist Sylas''s cartography of the Resonance Caverns has revealed sections that do not appear on any map — not Concordium survey maps, not Iron Hegemony mineral charts, not even the speculative Arcanum projections. Sealed chambers, acoustically isolated, with energy signatures that spike and then vanish whenever a detection instrument approaches. Whatever is in there chose to be unfindable. The Arcanum has chosen to find it anyway.', '{"npc_id": "npc_arcanum_archivist", "name": "Archivist Sylas", "location": "RESONANCE_CAVERNS"}'::jsonb, '{"min_level": 15, "reputation_required": 70, "required_quests": ["fq_arc_015"]}'::jsonb, '[{"type": "collect", "target": "specter_essence", "count": 4, "description": "Collect specter essence (x4). [Item: Specter Essence]"}, {"type": "kill", "target": "RESONANCE_BAT", "count": 4, "description": "Clear hostiles from unmapped sectors. [Resonance Bat]"}]'::jsonb, '{"exp": 430, "currency": 230, "crd": 0, "rep": 230, "items": [{"item_id": "neural_disruptor_module", "quantity": 1}], "reputation": 5}'::jsonb, false, false, 'fq_arc_017', false, NULL, NULL, NULL, 'quest_arcanum.json', 15)
