insert into public.quests (id, title, type, rank, faction, region, description, quest_giver, requirements, objectives, rewards, repeatable, daily, quest_chain_next, popup, popup_trigger, popup_level, popup_prerequisite, source_file, sort_order)
values ('fq_arc_017', 'What Was Meant to Stay Sealed', 'story', 'C', 'THE_ARCANUM_SEEKERS', 'RESONANCE_CAVERNS', 'The sealed chamber Archivist Sylas found is not just locked — it was engineered to resist entry, with Golem guardians reactivating every time a breach is attempted. (Location: Resonance Caverns, Scholar Elara) The Aethelgardians sealed something here deliberately, which means they knew it needed to be contained. High Seeker Elara Voss''s response to this is characteristic: ''Everything that was sealed was sealed by someone who was also afraid of knowing. We are not afraid.'' Breach the chamber. Document everything.', '{"npc_id": "npc_arcanum_scholar", "name": "High Seeker Elara Voss", "location": "RESONANCE_CAVERNS"}'::jsonb, '{"min_level": 16, "reputation_required": 75, "required_quests": ["fq_arc_016"]}'::jsonb, '[{"type": "collect", "target": "arcane_crystal_fragment", "count": 2, "description": "Collect arcane crystal fragment (x2). [Item: Arcane Crystal Fragment]"}, {"type": "kill", "target": "RESONANCE_GOLEM", "count": 2, "description": "Defeat Golems guarding the chamber. [Resonance Golem]"}]'::jsonb, '{"exp": 480, "currency": 260, "crd": 0, "rep": 260, "items": [{"item_id": "quantum_distortion_stone", "quantity": 1}], "reputation": 5}'::jsonb, false, false, 'fq_arc_018', false, NULL, NULL, NULL, 'quest_arcanum.json', 16)
