insert into public.quests (id, title, type, rank, faction, region, description, quest_giver, requirements, objectives, rewards, repeatable, daily, quest_chain_next, popup, popup_trigger, popup_level, popup_prerequisite, source_file, sort_order)
values ('fq_arc_018', 'The Voice of the Aethelgardians', 'story', 'C', 'THE_ARCANUM_SEEKERS', 'RESONANCE_CAVERNS', 'The artifacts from the sealed chamber contain Aethelgardian language fragments in a dialect that Archivist Sylas has never seen — older than the Siphon''s construction era, possibly older than anything in the Arcanum''s database. (Location: Resonance Caverns, Scholar Elara) High Seeker Elara Voss has begun a real-time translation and she cannot be interrupted. The Golems are fighting back. The Bats are swarming. Someone — or something — does not want those words spoken aloud again.', '{"npc_id": "npc_arcanum_scholar", "name": "High Seeker Elara Voss", "location": "RESONANCE_CAVERNS"}'::jsonb, '{"min_level": 17, "reputation_required": 80, "required_quests": ["fq_arc_017"]}'::jsonb, '[{"type": "kill", "target": "RESONANCE_GOLEM", "count": 3, "description": "Defend the translation site from Golem assault. [Resonance Golem]"}, {"type": "kill", "target": "RESONANCE_BAT", "count": 6, "description": "Eliminate Bats disrupting the ritual. [Resonance Bat]"}]'::jsonb, '{"exp": 550, "currency": 300, "crd": 0, "rep": 320, "items": [{"item_id": "memory_fragment_chip", "quantity": 3}], "reputation": 5}'::jsonb, false, false, 'fq_arc_019', false, NULL, NULL, NULL, 'quest_arcanum.json', 17)
