insert into public.quests (id, title, type, rank, faction, region, description, quest_giver, requirements, objectives, rewards, repeatable, daily, quest_chain_next, popup, popup_trigger, popup_level, popup_prerequisite, source_file, sort_order)
values ('fq_arc_019', 'The Sum of Lost Knowledge', 'story', 'C', 'THE_ARCANUM_SEEKERS', 'RESONANCE_CAVERNS', 'The Resonance Echo that formed in the deepest chamber is not a creature in any biological sense — it is the caverns'' accumulated Aethelgardian data coalesced into a coherent energy entity, the same phenomenon the ancient texts called ''a dreaming archive.'' The Arcanum has theorized about this. (Location: Resonance Caverns, Scholar Elara) High Seeker Elara Voss has written three papers about the theoretical possibility. She is almost incapable of hiding her awe as she orders you to defeat it and extract its data core.', '{"npc_id": "npc_arcanum_scholar", "name": "High Seeker Elara Voss", "location": "RESONANCE_CAVERNS"}'::jsonb, '{"min_level": 18, "reputation_required": 85, "required_quests": ["fq_arc_018"]}'::jsonb, '[{"type": "kill", "target": "RESONANCE_ECHO", "count": 1, "description": "Defeat the Resonance Echo."}, {"type": "kill", "target": "RESONANCE_GOLEM", "count": 2, "description": "Destroy Golems shielding the Echo. [Resonance Golem]"}]'::jsonb, '{"exp": 800, "currency": 450, "crd": 0, "rep": 450, "items": [{"item_id": "entropy_core", "quantity": 1}, {"item_id": "con_medium_hp_cell", "quantity": 3}], "reputation": 5}'::jsonb, false, false, 'fq_arc_020', false, NULL, NULL, NULL, 'quest_arcanum.json', 18)
