insert into public.quests (id, title, type, rank, faction, region, description, quest_giver, requirements, objectives, rewards, repeatable, daily, quest_chain_next, popup, popup_trigger, popup_level, popup_prerequisite, source_file, sort_order)
values ('fq_arc_020', 'The Spire Opens Its Deeper Doors', 'story', 'C', 'THE_ARCANUM_SEEKERS', 'OBSERVATORY_SPIRE', 'The Resonance Echo''s data core is being analyzed in the Observatory Spire''s highest laboratory. High Seeker Elara Voss has called you back — not with orders, but with something closer to an invitation. The Arcanum''s restricted archives, the ones the Concordium tried to confiscate twice, are being opened for your Advanced evaluation. What you learned in the Caverns was just the beginning. The Spire''s deeper doors require a key that can only be earned, not given. Quest giver: Scholar Elara at Observatory Spire Research Wing.', '{"npc_id": "npc_arcanum_scholar", "name": "High Seeker Elara Voss", "location": "OBSERVATORY_SPIRE"}'::jsonb, '{"min_level": 19, "reputation_required": 90, "required_quests": ["fq_arc_019"]}'::jsonb, '[{"type": "travel", "target": "OBSERVATORY_SPIRE", "count": 1, "description": "Return to the Observatory Spire."}, {"type": "collect", "target": "monster_material", "count": 1, "description": "Collect monster material (x1). [Item: Monster Material]"}]'::jsonb, '{"exp": 900, "currency": 500, "crd": 0, "rep": 500, "items": [{"item_id": "con_medium_hp_cell", "quantity": 5}, {"item_id": "con_medium_mp_cell", "quantity": 3}], "reputation": 5}'::jsonb, false, false, 'fq_arc_021', false, NULL, NULL, NULL, 'quest_arcanum.json', 19)
