insert into public.quests (id, title, type, rank, faction, region, description, quest_giver, requirements, objectives, rewards, repeatable, daily, quest_chain_next, popup, popup_trigger, popup_level, popup_prerequisite, source_file, sort_order)
values ('fq_arc_021', 'Forbidden Zones', 'exploration', 'B', 'THE_ARCANUM_SEEKERS', 'SHARD_PULSE_PEAK', 'The Shard Pulse Peak is a forbidden research zone. Ancient machines still operate there, pulsing with unknowable energy. The Arcanum has authorized your entry. Quest giver: Scholar Elara at Observatory Spire Research Wing.', '{"npc_id": "npc_arcanum_scholar", "name": "Scholar Elara", "location": "SHARD_PULSE_PEAK"}'::jsonb, '{"min_level": 20, "reputation_required": 1140, "required_quests": ["fq_arc_020"]}'::jsonb, '[{"type": "travel", "target": "SHARD_PULSE_PEAK", "count": 1, "description": "Ascend to the Shard Pulse Peak."}, {"type": "collect", "target": "thick_hide", "count": 2, "description": "Collect thick hide (x2). [Item: Thick Hide]"}]'::jsonb, '{"exp": 600, "currency": 350, "crd": 105, "rep": 350, "items": [{"item_id": "con_nutrient_ration", "quantity": 3}], "reputation": 10}'::jsonb, false, false, 'fq_arc_022', false, NULL, NULL, NULL, 'quest_arcanum.json', 20)
