values ('fq_arc_022', 'Sentinel Disruption', 'hunt', 'B', 'THE_ARCANUM_SEEKERS', 'SHARD_PULSE_PEAK', 'Shard Pulse Sentinels patrol the peak''s machine platforms. (Location: Shard Pulse Peak, Watcher Vane) Their energy signatures suggest they are guardians of dormant technology.', '{"npc_id": "npc_peak_watcher", "name": "Watcher Vane", "location": "SHARD_PULSE_PEAK"}'::jsonb, '{"min_level": 21, "reputation_required": 1200, "required_quests": ["fq_arc_021"]}'::jsonb, '[{"type": "kill", "target": "SHARD_PULSE_SENTINEL", "count": 5, "description": "Disable Shard Pulse Sentinels for analysis."}, {"type": "collect", "target": "arcane_crystal_fragment", "count": 2, "description": "Collect arcane crystal fragment (x2). [Item: Arcane Crystal Fragment]"}]'::jsonb, '{"exp": 650, "currency": 380, "crd": 114, "rep": 380, "items": [{"item_id": "damaged_servo_motor", "quantity": 2}], "reputation": 10}'::jsonb, false, false, 'fq_arc_023', false, NULL, NULL, NULL, 'quest_arcanum.json', 21)
