values ('fq_arc_023', 'Guardian Protocols', 'boss', 'B', 'THE_ARCANUM_SEEKERS', 'SHARD_PULSE_PEAK', 'Shard Pulse Guardians are elite Sentinel variants. (Location: Shard Pulse Peak, Watcher Vane) They protect the peak''s central machine. Disable them and access the machine''s data terminal.', '{"npc_id": "npc_peak_watcher", "name": "Watcher Vane", "location": "SHARD_PULSE_PEAK"}'::jsonb, '{"min_level": 22, "reputation_required": 1260, "required_quests": ["fq_arc_022"]}'::jsonb, '[{"type": "kill", "target": "SHARD_PULSE_GUARDIAN", "count": 2, "description": "Defeat Shard Pulse Guardians."}, {"type": "collect", "target": "crystal_core", "count": 1, "description": "Collect crystal core (x1). [Item: Crystal Core]"}]'::jsonb, '{"exp": 750, "currency": 420, "crd": 126, "rep": 450, "items": [{"item_id": "processor_cooling_unit", "quantity": 1}], "reputation": 10}'::jsonb, false, false, 'fq_arc_024', false, NULL, NULL, NULL, 'quest_arcanum.json', 22)
