values ('fq_arc_024', 'Leviathan''s Depth', 'boss', 'B', 'THE_ARCANUM_SEEKERS', 'SHARD_PULSE_PEAK', 'A Sunken Aethel Leviathan has been detected in the peak''s subterranean lake. (Location: Shard Pulse Peak, Researcher Vin) Its biology may hold secrets of Aethel conversion. Capture tissue samples.', '{"npc_id": "npc_researcher_vin", "name": "Researcher Vin", "location": "SHARD_PULSE_PEAK"}'::jsonb, '{"min_level": 23, "reputation_required": 1320, "required_quests": ["fq_arc_023"]}'::jsonb, '[{"type": "kill", "target": "SUNKEN_AETHEL_LEVIATHAN", "count": 1, "description": "Defeat the Sunken Aethel Leviathan."}, {"type": "collect", "target": "leviathan_scale", "count": 3, "description": "Collect leviathan scale (x3). [Item: Leviathan Scale]"}]'::jsonb, '{"exp": 850, "currency": 460, "crd": 138, "rep": 480, "items": [{"item_id": "aethel_core_shard", "quantity": 3}], "reputation": 10}'::jsonb, false, false, 'fq_arc_025', false, NULL, NULL, NULL, 'quest_arcanum.json', 23)
