values ('fq_arc_025', 'Tyrant''s Pulse', 'boss', 'B', 'THE_ARCANUM_SEEKERS', 'SHARD_PULSE_PEAK', 'The Shard Pulse Tyrant is the apex guardian of the peak. (Location: Shard Pulse Peak, Scholar Elara) Its energy signature matches Precursor command protocols. Disable it to access the master terminal.', '{"npc_id": "npc_arcanum_scholar", "name": "Scholar Elara", "location": "SHARD_PULSE_PEAK"}'::jsonb, '{"min_level": 24, "reputation_required": 1380, "required_quests": ["fq_arc_024"]}'::jsonb, '[{"type": "kill", "target": "SHARD_PULSE_TYRANT", "count": 1, "description": "Defeat the Shard Pulse Tyrant."}, {"type": "kill", "target": "SHARD_PULSE_GUARDIAN", "count": 1, "description": "Clear Guardian escorts. [Shard Pulse Guardian]"}]'::jsonb, '{"exp": 1000, "currency": 550, "crd": 165, "rep": 550, "items": [{"item_id": "titan_core", "quantity": 1}], "reputation": 10}'::jsonb, false, false, 'fq_arc_026', false, NULL, NULL, NULL, 'quest_arcanum.json', 24)
