values ('fq_arc_026', 'Storm Serpent', 'boss', 'B', 'THE_ARCANUM_SEEKERS', 'SHARD_PULSE_PEAK', 'A Storm Rift Serpent has been drawn to the peak''s energy. (Location: Shard Pulse Peak, Researcher Vin) These creatures ride electromagnetic currents. Harvest its scales for the Arcanum''s armory.', '{"npc_id": "npc_researcher_vin", "name": "Researcher Vin", "location": "SHARD_PULSE_PEAK"}'::jsonb, '{"min_level": 25, "reputation_required": 1440, "required_quests": ["fq_arc_025"]}'::jsonb, '[{"type": "kill", "target": "STORM_RIFT_SERPENT", "count": 1, "description": "Defeat the Storm Rift Serpent."}, {"type": "collect", "target": "storm_core", "count": 2, "description": "Collect storm core (x2). [Item: Storm Core]"}]'::jsonb, '{"exp": 900, "currency": 500, "crd": 150, "rep": 520, "items": [{"item_id": "ancient_scale", "quantity": 2}], "reputation": 10}'::jsonb, false, false, 'fq_arc_027', false, NULL, NULL, NULL, 'quest_arcanum.json', 25)
