values ('fq_arc_027', 'Celestial Observation', 'exploration', 'B', 'THE_ARCANUM_SEEKERS', 'AETHEL_STORM_BELT', 'The Aethel Storm Belt is a contested zone of intense electromagnetic activity. The Arcanum seeks to establish an observation post to study celestial phenomena. Quest giver: Scholar Elara at Observatory Spire Research Wing.', '{"npc_id": "npc_arcanum_scholar", "name": "Scholar Elara", "location": "AETHEL_STORM_BELT"}'::jsonb, '{"min_level": 26, "reputation_required": 1500, "required_quests": ["fq_arc_026"]}'::jsonb, '[{"type": "travel", "target": "AETHEL_STORM_BELT", "count": 1, "description": "Enter the Aethel Storm Belt."}, {"type": "collect", "target": "desert_chitin", "count": 2, "description": "Collect desert chitin (x2). [Item: Desert Chitin]"}]'::jsonb, '{"exp": 700, "currency": 400, "crd": 120, "rep": 400, "items": [{"item_id": "con_nutrient_ration", "quantity": 3}], "reputation": 10}'::jsonb, false, false, 'fq_arc_028', false, NULL, NULL, NULL, 'quest_arcanum.json', 26)
