values ('fq_arc_028', 'Storm Wranglers', 'hunt', 'B', 'THE_ARCANUM_SEEKERS', 'AETHEL_STORM_BELT', 'Storm Rift Serpents dominate the Storm Belt. (Location: Aethel Storm Belt, Researcher Vin) Their electromagnetic nature disrupts our instruments. Thin their population.', '{"npc_id": "npc_researcher_vin", "name": "Researcher Vin", "location": "AETHEL_STORM_BELT"}'::jsonb, '{"min_level": 27, "reputation_required": 1560, "required_quests": ["fq_arc_027"]}'::jsonb, '[{"type": "kill", "target": "STORM_RIFT_SERPENT", "count": 3, "description": "Defeat Storm Rift Serpents in the Belt."}, {"type": "collect", "target": "storm_core", "count": 2, "description": "Collect storm core (x2). [Item: Storm Core]"}]'::jsonb, '{"exp": 750, "currency": 430, "crd": 129, "rep": 430, "items": [{"item_id": "power_regulator_core", "quantity": 1}], "reputation": 10}'::jsonb, false, false, 'fq_arc_029', false, NULL, NULL, NULL, 'quest_arcanum.json', 27)
