values ('fq_arc_029', 'Leviathan Hunt', 'boss', 'B', 'THE_ARCANUM_SEEKERS', 'AETHEL_STORM_BELT', 'Multiple Sunken Aethel Leviathans have migrated into the Storm Belt. (Location: Aethel Storm Belt, Scholar Elara) Their migration pattern is unprecedented — and dangerous to the observation post.', '{"npc_id": "npc_arcanum_scholar", "name": "Scholar Elara", "location": "AETHEL_STORM_BELT"}'::jsonb, '{"min_level": 28, "reputation_required": 1620, "required_quests": ["fq_arc_028"]}'::jsonb, '[{"type": "kill", "target": "SUNKEN_AETHEL_LEVIATHAN", "count": 2, "description": "Defeat Leviathans threatening the observation post. [Sunken Aethel Leviathan]"}, {"type": "kill", "target": "STORM_RIFT_SERPENT", "count": 2, "description": "Clear Serpent escorts. [Storm Rift Serpent]"}]'::jsonb, '{"exp": 900, "currency": 520, "crd": 156, "rep": 520, "items": [{"item_id": "aethel_fragment", "quantity": 2}], "reputation": 10}'::jsonb, false, false, 'fq_arc_030', false, NULL, NULL, NULL, 'quest_arcanum.json', 28)
