values ('fq_arc_030', 'The Second Ascension', 'story', 'B', 'THE_ARCANUM_SEEKERS', 'OBSERVATORY_SPIRE', 'Archsage Myr has determined you are ready for Ascension. Return to the Observatory Spire for the arcane elevation ritual.', '{"npc_id": "npc_arcanum_class_trainer", "name": "Archsage Myr", "location": "OBSERVATORY_SPIRE"}'::jsonb, '{"min_level": 29, "reputation_required": 95, "required_quests": ["fq_arc_029"]}'::jsonb, '[{"type": "interact", "target": "npc_arcanum_class_trainer", "count": 1, "description": "Report to Archsage Myr for Ascension evaluation. (Archsage Myr at Observatory Spire Academy)"}, {"type": "kill", "target": "RESONANCE_ECHO", "count": 1, "description": "Defeat the Resonance Echo to prove your arcane growth."}, {"type": "kill", "target": "SHARD_PULSE_TYRANT", "count": 1, "description": "Defeat a Shard Pulse Tyrant as your advanced trial."}]'::jsonb, '{"exp": 2500, "currency": 1200, "crd": 360, "rep": 800, "items": [{"item_id": "con_elite_recovery_pack", "quantity": 2}, {"item_id": "astral_phase_crystal_pure", "quantity": 1}], "reputation": 10}'::jsonb, false, false, 'fq_arc_031', true, 'on_quest_complete', 29, 'fq_arc_029', 'quest_arcanum.json', 29)
