values ('fq_arc_031', 'Orbital Ambitions', 'exploration', 'A', 'THE_ARCANUM_SEEKERS', 'ORBITAL_SENTINEL_COMMAND', 'The Arcanum Seekers require access to orbital platforms. Knowledge of the heavens is the next frontier. Establish our presence at the Orbital Sentinel Command. Quest giver: Scholar Elara at Observatory Spire Research Wing.', '{"npc_id": "npc_arcanum_scholar", "name": "Scholar Elara", "location": "ORBITAL_SENTINEL_COMMAND"}'::jsonb, '{"min_level": 30, "reputation_required": 1740, "required_quests": ["fq_arc_030"]}'::jsonb, '[{"type": "travel", "target": "ORBITAL_SENTINEL_COMMAND", "count": 1, "description": "Report to Orbital Sentinel Command."}, {"type": "collect", "target": "monster_material", "count": 1, "description": "Collect monster material (x1). [Item: Monster Material]"}]'::jsonb, '{"exp": 900, "currency": 500, "crd": 250, "rep": 500, "items": [{"item_id": "con_elite_recovery_pack", "quantity": 1}], "reputation": 25}'::jsonb, false, false, 'fq_arc_032', false, NULL, NULL, NULL, 'quest_arcanum.json', 30)
