values ('fq_arc_032', 'Celestial Hunt', 'hunt', 'A', 'THE_ARCANUM_SEEKERS', 'CRADLE_EXPANSE', 'The Ashen Drake has been sighted from orbit. The Arcanum needs direct observation data. Track the Drake in the Cradle Expanse. Quest giver: Scholar Elara at Observatory Spire Research Wing.', '{"npc_id": "npc_arcanum_scholar", "name": "Scholar Elara", "location": "CRADLE_EXPANSE"}'::jsonb, '{"min_level": 31, "reputation_required": 1800, "required_quests": ["fq_arc_031"]}'::jsonb, '[{"type": "kill", "target": "ASHEN_DRAKE", "count": 1, "description": "Engage and observe the Ashen Drake. Survival is sufficient."}, {"type": "collect", "target": "drake_heart", "count": 2, "description": "Collect drake heart (x2). [Item: Drake Heart]"}]'::jsonb, '{"exp": 1200, "currency": 650, "crd": 325, "rep": 650, "items": [{"item_id": "drake_heart", "quantity": 1}], "reputation": 25}'::jsonb, false, false, 'fq_arc_033', false, NULL, NULL, NULL, 'quest_arcanum.json', 31)
