values ('fq_arc_033', 'Behemoth Study', 'boss', 'A', 'THE_ARCANUM_SEEKERS', 'CRADLE_EXPANSE', 'Aethel Behemoths possess unusual regenerative properties. (Location: Cradle Expanse, Researcher Vin) The Arcanum believes their biology can unlock new alchemical formulas.', '{"npc_id": "npc_researcher_vin", "name": "Researcher Vin", "location": "CRADLE_EXPANSE"}'::jsonb, '{"min_level": 32, "reputation_required": 1860, "required_quests": ["fq_arc_032"]}'::jsonb, '[{"type": "kill", "target": "AETHEL_BEHEMOTH", "count": 2, "description": "Defeat Aethel Behemoths for tissue samples."}, {"type": "collect", "target": "raw_aethel_core", "count": 2, "description": "Collect raw aethel core (x2). [Item: Raw Aethel Core]"}]'::jsonb, '{"exp": 1400, "currency": 750, "crd": 375, "rep": 750, "items": [{"item_id": "mutagen_catalyst", "quantity": 1}], "reputation": 25}'::jsonb, false, false, 'fq_arc_034', false, NULL, NULL, NULL, 'quest_arcanum.json', 32)
