values ('fq_arc_034', 'Void Alchemy', 'boss', 'A', 'THE_ARCANUM_SEEKERS', 'CRADLE_EXPANSE', 'Aethel Void Channelers are conducting void-alchemical rituals. (Location: Cradle Expanse, Scholar Elara) Steal their research — it may contain the key to void energy transmutation.', '{"npc_id": "npc_arcanum_scholar", "name": "Scholar Elara", "location": "CRADLE_EXPANSE"}'::jsonb, '{"min_level": 33, "reputation_required": 1920, "required_quests": ["fq_arc_033"]}'::jsonb, '[{"type": "kill", "target": "AETHEL_VOID_CHANNELER", "count": 4, "description": "Interrupt the void-alchemical rituals. [Aethel Void Channeler]"}, {"type": "collect", "target": "void_channeler_core", "count": 2, "description": "Collect void channeler core (x2). [Item: Void Channeler Core]"}]'::jsonb, '{"exp": 1600, "currency": 850, "crd": 425, "rep": 850, "items": [{"item_id": "void_fragment", "quantity": 3}], "reputation": 25}'::jsonb, false, false, 'fq_arc_035', false, NULL, NULL, NULL, 'quest_arcanum.json', 33)
