values ('fq_arc_035', 'Abyssal Specimen', 'boss', 'A', 'THE_ARCANUM_SEEKERS', 'CRADLE_EXPANSE', 'Aethel Abyssal Reavers are creatures of pure void energy. (Location: Cradle Expanse, Researcher Vin) The Arcanum requires a live essence sample for the restricted archive.', '{"npc_id": "npc_researcher_vin", "name": "Researcher Vin", "location": "CRADLE_EXPANSE"}'::jsonb, '{"min_level": 34, "reputation_required": 1980, "required_quests": ["fq_arc_034"]}'::jsonb, '[{"type": "kill", "target": "AETHEL_ABYSSAL_REAVER", "count": 3, "description": "Defeat Abyssal Reavers and extract essence. [Aethel Abyssal Reaver]"}, {"type": "collect", "target": "void_channeler_core", "count": 1, "description": "Collect void channeler core (x1). [Item: Void Channeler Core]"}]'::jsonb, '{"exp": 1800, "currency": 950, "crd": 475, "rep": 950, "items": [{"item_id": "event_horizon_fragment", "quantity": 1}], "reputation": 25}'::jsonb, false, false, 'fq_arc_036', false, NULL, NULL, NULL, 'quest_arcanum.json', 34)
