values ('fq_arc_036', 'Archive Defense', 'hunt', 'A', 'THE_ARCANUM_SEEKERS', 'ORBITAL_SENTINEL_COMMAND', 'Rival factions are probing Arcanum orbital archives. (Location: Orbital Sentinel Command, Archivist Sylas) The knowledge stored here must be protected at all costs.', '{"npc_id": "npc_arcanum_archivist", "name": "Archivist Sylas", "location": "ORBITAL_SENTINEL_COMMAND"}'::jsonb, '{"min_level": 35, "reputation_required": 2040, "required_quests": ["fq_arc_035"]}'::jsonb, '[{"type": "kill", "target": "AETHEL_RIFT_STALKER", "count": 6, "description": "Repel intruders from the orbital archives. [Aethel Rift Stalker]"}, {"type": "kill", "target": "AETHEL_VOID_CHANNELER", "count": 3, "description": "Neutralize hostile Channelers. [Aethel Void Channeler]"}]'::jsonb, '{"exp": 1500, "currency": 800, "crd": 400, "rep": 800, "items": [{"item_id": "con_elite_recovery_pack", "quantity": 3}], "reputation": 25}'::jsonb, false, false, 'fq_arc_037', false, NULL, NULL, NULL, 'quest_arcanum.json', 35)
