values ('fq_arc_037', 'Drake''s Alchemy', 'boss', 'A', 'THE_ARCANUM_SEEKERS', 'CRADLE_EXPANSE', 'The Ashen Drake''s fire contains unique alchemical properties. (Location: Cradle Expanse, Scholar Elara) The Arcanum must obtain a fresh flame sample — directly from the source if necessary.', '{"npc_id": "npc_arcanum_scholar", "name": "Scholar Elara", "location": "CRADLE_EXPANSE"}'::jsonb, '{"min_level": 36, "reputation_required": 2100, "required_quests": ["fq_arc_036"]}'::jsonb, '[{"type": "kill", "target": "ASHEN_DRAKE", "count": 1, "description": "Confront the Ashen Drake for a flame sample."}, {"type": "collect", "target": "drake_heart", "count": 1, "description": "Collect drake heart (x1). [Item: Drake Heart]"}]'::jsonb, '{"exp": 2500, "currency": 1300, "crd": 650, "rep": 900, "items": [{"item_id": "drake_heart", "quantity": 2}], "reputation": 25}'::jsonb, false, false, 'fq_arc_038', false, NULL, NULL, NULL, 'quest_arcanum.json', 36)
