values ('fq_arc_038', 'Corrupted Research', 'hunt', 'A', 'THE_ARCANUM_SEEKERS', 'CRADLE_EXPANSE', 'Aethel Corrupted Behemoths are the result of failed void experiments by rival factions. (Location: Cradle Expanse, Researcher Vin) Clean up their mess and collect the corrupted data.', '{"npc_id": "npc_researcher_vin", "name": "Researcher Vin", "location": "CRADLE_EXPANSE"}'::jsonb, '{"min_level": 37, "reputation_required": 2160, "required_quests": ["fq_arc_037"]}'::jsonb, '[{"type": "kill", "target": "AETHEL_CORRUPTED_BEHEMOTH", "count": 2, "description": "Destroy Corrupted Behemoths. [Aethel Corrupted Behemoth]"}, {"type": "collect", "target": "crystal_core", "count": 2, "description": "Collect crystal core (x2). [Item: Crystal Core]"}]'::jsonb, '{"exp": 1700, "currency": 900, "crd": 450, "rep": 900, "items": [{"item_id": "corrupted_synapse_cluster", "quantity": 1}], "reputation": 25}'::jsonb, false, false, 'fq_arc_039', false, NULL, NULL, NULL, 'quest_arcanum.json', 37)
