values ('fq_arc_039', 'Abyssal Raid', 'boss', 'A', 'THE_ARCANUM_SEEKERS', 'CRADLE_EXPANSE', 'Multiple Abyssal Reavers threaten to overrun the orbital research stations. (Location: Cradle Expanse, Scholar Elara) The Arcanum cannot afford to lose decades of orbital data.', '{"npc_id": "npc_arcanum_scholar", "name": "Scholar Elara", "location": "CRADLE_EXPANSE"}'::jsonb, '{"min_level": 38, "reputation_required": 2220, "required_quests": ["fq_arc_038"]}'::jsonb, '[{"type": "kill", "target": "AETHEL_ABYSSAL_REAVER", "count": 5, "description": "Defeat the Abyssal Reaver assault. [Aethel Abyssal Reaver]"}, {"type": "kill", "target": "AETHEL_VOID_CHANNELER", "count": 3, "description": "Silence the summoning Channelers. [Aethel Void Channeler]"}]'::jsonb, '{"exp": 2000, "currency": 1100, "crd": 550, "rep": 1100, "items": [{"item_id": "gravity_well_core", "quantity": 1}], "reputation": 25}'::jsonb, false, false, 'fq_arc_040', false, NULL, NULL, NULL, 'quest_arcanum.json', 38)
