values ('fq_arc_040', 'Master of the Arcane', 'story', 'A', 'THE_ARCANUM_SEEKERS', 'OBSERVATORY_SPIRE', 'The final trial for Master rank. (Location: Observatory Spire, Scholar Elara) Defeat the Ashen Drake and two elite guardians to gain access to the Arcanum''s most restricted orbital archives.', '{"npc_id": "npc_arcanum_scholar", "name": "Scholar Elara", "location": "OBSERVATORY_SPIRE"}'::jsonb, '{"min_level": 39, "reputation_required": 105, "required_quests": ["fq_arc_039"]}'::jsonb, '[{"type": "kill", "target": "ASHEN_DRAKE", "count": 1, "description": "Defeat the Ashen Drake."}, {"type": "kill", "target": "AETHEL_BEHEMOTH", "count": 1, "description": "Destroy an Aethel Behemoth."}, {"type": "kill", "target": "AETHEL_ABYSSAL_REAVER", "count": 1, "description": "Slay an Abyssal Reaver. [Aethel Abyssal Reaver]"}]'::jsonb, '{"exp": 5000, "currency": 2500, "crd": 1250, "rep": 2000, "items": [{"item_id": "drake_heart", "quantity": 1}, {"item_id": "entropy_core", "quantity": 1}, {"item_id": "con_elite_recovery_pack", "quantity": 5}], "reputation": 25}'::jsonb, false, false, 'fq_arc_041', false, NULL, NULL, NULL, 'quest_arcanum.json', 39)
