values ('fq_arc_041', 'Echoes of the Past', 'exploration', 'S', 'THE_ARCANUM_SEEKERS', 'VOID_ECHO_CHASM', 'The Void Echo Chasm contains echoes of all knowledge ever lost. The Arcanum Seeker''s greatest ambition: enter the chasm and retrieve what was forgotten. Quest giver: Scholar Elara at Observatory Spire Research Wing.', '{"npc_id": "npc_arcanum_scholar", "name": "Scholar Elara", "location": "VOID_ECHO_CHASM"}'::jsonb, '{"min_level": 40, "reputation_required": 2340, "required_quests": ["fq_arc_040"]}'::jsonb, '[{"type": "travel", "target": "VOID_ECHO_CHASM", "count": 1, "description": "Enter the Void Echo Chasm."}, {"type": "collect", "target": "void_channeler_core", "count": 3, "description": "Collect void channeler core (x3). [Item: Void Channeler Core]"}]'::jsonb, '{"exp": 1800, "currency": 900, "crd": 450, "rep": 600, "items": [{"item_id": "void_fragment", "quantity": 3}], "reputation": 50}'::jsonb, false, false, 'fq_arc_042', false, NULL, NULL, NULL, 'quest_arcanum.json', 40)
