values ('fq_arc_042', 'Void Reaver Research', 'hunt', 'S', 'THE_ARCANUM_SEEKERS', 'VOID_ECHO_CHASM', 'Void Reavers are the most stable void entities. (Location: Void Echo Chasm, Researcher Vin) Study them extensively — their nature may reveal how to safely harness void energy.', '{"npc_id": "npc_researcher_vin", "name": "Researcher Vin", "location": "VOID_ECHO_CHASM"}'::jsonb, '{"min_level": 41, "reputation_required": 2400, "required_quests": ["fq_arc_041"]}'::jsonb, '[{"type": "kill", "target": "VOID_REAVER", "count": 5, "description": "Defeat Void Reavers for research."}, {"type": "collect", "target": "void_fragment", "count": 1, "description": "Collect void fragment (x1). [Item: Void Fragment]"}]'::jsonb, '{"exp": 1900, "currency": 950, "crd": 475, "rep": 650, "items": [{"item_id": "void_core", "quantity": 1}], "reputation": 50}'::jsonb, false, false, 'fq_arc_043', false, NULL, NULL, NULL, 'quest_arcanum.json', 41)
