values ('fq_arc_043', 'Forbidden Rituals', 'story', 'S', 'THE_ARCANUM_SEEKERS', 'VOID_ECHO_CHASM', 'Ancient void rituals have been detected in the chasm depths. (Location: Void Echo Chasm, Scholar Elara) The energy signatures match the Abyss Harbinger myth. Investigate with extreme caution.', '{"npc_id": "npc_arcanum_scholar", "name": "Scholar Elara", "location": "VOID_ECHO_CHASM"}'::jsonb, '{"min_level": 42, "reputation_required": 130, "required_quests": ["fq_arc_042"]}'::jsonb, '[{"type": "kill", "target": "AETHEL_VOID_CHANNELER", "count": 6, "description": "Interrupt the forbidden void rituals. [Aethel Void Channeler]"}, {"type": "collect", "target": "void_channeler_core", "count": 3, "description": "Collect void channeler core (x3). [Item: Void Channeler Core]"}]'::jsonb, '{"exp": 2100, "currency": 1050, "crd": 525, "rep": 700, "items": [{"item_id": "event_horizon_fragment", "quantity": 2}], "reputation": 50}'::jsonb, false, false, 'fq_arc_044', false, NULL, NULL, NULL, 'quest_arcanum.json', 42)
