values ('fq_arc_044', 'Abyssal Harvest', 'hunt', 'S', 'THE_ARCANUM_SEEKERS', 'VOID_ECHO_CHASM', 'Abyssal Reavers contain concentrated void essence — the most potent alchemical ingredient known. (Location: Void Echo Chasm, Researcher Vin) Harvest them for the Arcanum''s grand experiment.', '{"npc_id": "npc_researcher_vin", "name": "Researcher Vin", "location": "VOID_ECHO_CHASM"}'::jsonb, '{"min_level": 43, "reputation_required": 2520, "required_quests": ["fq_arc_043"]}'::jsonb, '[{"type": "kill", "target": "AETHEL_ABYSSAL_REAVER", "count": 5, "description": "Harvest Abyssal Reavers for void essence. [Aethel Abyssal Reaver]"}, {"type": "collect", "target": "void_channeler_core", "count": 3, "description": "Collect void channeler core (x3). [Item: Void Channeler Core]"}]'::jsonb, '{"exp": 2200, "currency": 1100, "crd": 550, "rep": 750, "items": [{"item_id": "void_crystal_shard", "quantity": 2}], "reputation": 50}'::jsonb, false, false, 'fq_arc_045', false, NULL, NULL, NULL, 'quest_arcanum.json', 43)
