values ('fq_arc_045', 'Behemoth Experiment', 'boss', 'S', 'THE_ARCANUM_SEEKERS', 'VOID_ECHO_CHASM', 'Aethel Corrupted Behemoths in the chasm show signs of controlled mutation. (Location: Void Echo Chasm, Researcher Vin) The Arcanum hypothesizes they were someone''s experiment. Collect tissue for comparative analysis.', '{"npc_id": "npc_researcher_vin", "name": "Researcher Vin", "location": "VOID_ECHO_CHASM"}'::jsonb, '{"min_level": 44, "reputation_required": 2580, "required_quests": ["fq_arc_044"]}'::jsonb, '[{"type": "kill", "target": "AETHEL_CORRUPTED_BEHEMOTH", "count": 3, "description": "Defeat Corrupted Behemoths for tissue samples. [Aethel Corrupted Behemoth]"}, {"type": "collect", "target": "raw_aethel_fragment", "count": 1, "description": "Collect raw aethel fragment (x1). [Item: Raw Aethel Fragment]"}]'::jsonb, '{"exp": 2500, "currency": 1300, "crd": 650, "rep": 800, "items": [{"item_id": "corrupted_synapse_cluster", "quantity": 2}], "reputation": 50}'::jsonb, false, false, 'fq_arc_046', false, NULL, NULL, NULL, 'quest_arcanum.json', 44)
