values ('fq_arc_046', 'Fragmented Souls', 'story', 'S', 'THE_ARCANUM_SEEKERS', 'VOID_ECHO_CHASM', 'Soul Fragmenters tear apart the boundary between consciousness and void. (Location: Void Echo Chasm, Scholar Elara) The Arcanum believes studying them could unlock the secrets of consciousness itself.', '{"npc_id": "npc_arcanum_scholar", "name": "Scholar Elara", "location": "VOID_ECHO_CHASM"}'::jsonb, '{"min_level": 45, "reputation_required": 180, "required_quests": ["fq_arc_045"]}'::jsonb, '[{"type": "kill", "target": "SOUL_FRAGMENTER", "count": 2, "description": "Defeat Soul Fragmenters for consciousness study."}, {"type": "collect", "target": "monster_material", "count": 1, "description": "Collect monster material (x1). [Item: Monster Material]"}]'::jsonb, '{"exp": 3000, "currency": 1600, "crd": 800, "rep": 1000, "items": [{"item_id": "brainwave_oscillator", "quantity": 2}], "reputation": 50}'::jsonb, false, false, 'fq_arc_047', false, NULL, NULL, NULL, 'quest_arcanum.json', 45)
