values ('fq_arc_047', 'Chrono Anomaly', 'boss', 'S', 'THE_ARCANUM_SEEKERS', 'VOID_ECHO_CHASM', 'Chrono Wraiths warp time around them. (Location: Void Echo Chasm, Scholar Elara) If the Arcanum can understand their temporal mechanics, the implications for knowledge preservation are infinite.', '{"npc_id": "npc_arcanum_scholar", "name": "Scholar Elara", "location": "VOID_ECHO_CHASM"}'::jsonb, '{"min_level": 46, "reputation_required": 2700, "required_quests": ["fq_arc_046"]}'::jsonb, '[{"type": "kill", "target": "CHRONO_WRAITH", "count": 2, "description": "Defeat Chrono Wraiths for temporal research."}, {"type": "collect", "target": "core_fragment", "count": 1, "description": "Collect core fragment (x1). [Item: Core Fragment]"}]'::jsonb, '{"exp": 3500, "currency": 1800, "crd": 900, "rep": 1100, "items": [{"item_id": "quantum_distortion_stone", "quantity": 2}], "reputation": 50}'::jsonb, false, false, 'fq_arc_048', false, NULL, NULL, NULL, 'quest_arcanum.json', 46)
