values ('fq_arc_048', 'Jotunn Biology', 'boss', 'S', 'THE_ARCANUM_SEEKERS', 'VOID_ECHO_CHASM', 'Gigantic Jotunns are biological impossibilities. (Location: Void Echo Chasm, Researcher Vin) Their existence defies known science. The Arcanum must study one up close.', '{"npc_id": "npc_researcher_vin", "name": "Researcher Vin", "location": "VOID_ECHO_CHASM"}'::jsonb, '{"min_level": 47, "reputation_required": 2760, "required_quests": ["fq_arc_047"]}'::jsonb, '[{"type": "kill", "target": "GIGANTIC_JOTUNN", "count": 1, "description": "Defeat a Gigantic Jotunn for biological study."}, {"type": "collect", "target": "monster_material", "count": 1, "description": "Collect monster material (x1). [Item: Monster Material]"}]'::jsonb, '{"exp": 3500, "currency": 1800, "crd": 900, "rep": 1000, "items": [{"item_id": "titan_core", "quantity": 1}], "reputation": 50}'::jsonb, false, false, 'fq_arc_049', false, NULL, NULL, NULL, 'quest_arcanum.json', 47)
