values ('fq_arc_049', 'Heart of Knowledge', 'exploration', 'S', 'THE_ARCANUM_SEEKERS', 'SHATTERED_HEART', 'The Shattered Heart is the ultimate repository of Precursor knowledge. The Arcanum has waited centuries for this moment. Enter and claim what is ours. Quest giver: Scholar Elara at Observatory Spire Research Wing.', '{"npc_id": "npc_arcanum_scholar", "name": "Scholar Elara", "location": "SHATTERED_HEART"}'::jsonb, '{"min_level": 48, "reputation_required": 2820, "required_quests": ["fq_arc_048"]}'::jsonb, '[{"type": "travel", "target": "SHATTERED_HEART", "count": 1, "description": "Enter the Shattered Heart."}, {"type": "collect", "target": "abyss_fragment", "count": 2, "description": "Collect abyss fragment (x2). [Item: Abyss Fragment]"}]'::jsonb, '{"exp": 2500, "currency": 1300, "crd": 650, "rep": 800, "items": [{"item_id": "memory_fragment_chip", "quantity": 3}], "reputation": 50}'::jsonb, false, false, 'fq_arc_050', false, NULL, NULL, NULL, 'quest_arcanum.json', 48)
