values ('fq_arc_050', 'Siphoning the Drake', 'boss', 'S', 'THE_ARCANUM_SEEKERS', 'SHATTERED_HEART', 'The Ashen Drake''s heart contains the secret of eternal fire — the ultimate alchemical catalyst. (Location: Shattered Heart, Scholar Elara) The Arcanum demands it. Raid Tier-1: claim the Drake''s heart for the grand experiment.', '{"npc_id": "npc_arcanum_scholar", "name": "Scholar Elara", "location": "SHATTERED_HEART"}'::jsonb, '{"min_level": 49, "reputation_required": 2880, "required_quests": ["fq_arc_049"]}'::jsonb, '[{"type": "kill", "target": "ASHEN_DRAKE", "count": 1, "description": "Defeat the Ashen Drake in its lair."}, {"type": "kill", "target": "DRAKE_MINION", "count": 5, "description": "Clear Drake Minions from the lair."}, {"type": "collect", "target": "ancient_scale", "count": 1, "description": "Collect ancient scale (x1). [Item: Ancient Scale]"}]'::jsonb, '{"exp": 8000, "currency": 4000, "crd": 2000, "rep": 2500, "items": [{"item_id": "drake_heart", "quantity": 2}, {"item_id": "ancient_scale", "quantity": 1}, {"item_id": "con_elite_recovery_pack", "quantity": 5}], "reputation": 50}'::jsonb, false, false, 'fq_arc_051', false, NULL, NULL, NULL, 'quest_arcanum.json', 49)
