values ('fq_arc_051', 'Fragmented Reality', 'boss', 'S', 'THE_ARCANUM_SEEKERS', 'VOID_ECHO_CHASM', 'Soul Fragmenters are multiplying across the chasm. (Location: Void Echo Chasm, Scholar Elara) Each one tears a hole in the fabric of consciousness. The Arcanum must contain them to prevent a reality cascade.', '{"npc_id": "npc_arcanum_scholar", "name": "Scholar Elara", "location": "VOID_ECHO_CHASM"}'::jsonb, '{"min_level": 50, "reputation_required": 2940, "required_quests": ["fq_arc_050"]}'::jsonb, '[{"type": "kill", "target": "SOUL_FRAGMENTER", "count": 3, "description": "Defeat three Soul Fragmenters."}, {"type": "collect", "target": "core_fragment", "count": 3, "description": "Collect core fragment (x3). [Item: Core Fragment]"}]'::jsonb, '{"exp": 6000, "currency": 3000, "crd": 1500, "rep": 2000, "items": [{"item_id": "brainwave_reader", "quantity": 1}], "reputation": 50}'::jsonb, false, false, 'fq_arc_052', false, NULL, NULL, NULL, 'quest_arcanum.json', 50)
