values ('fq_arc_052', 'Void Dominance', 'hunt', 'S', 'THE_ARCANUM_SEEKERS', 'VOID_ECHO_CHASM', 'The Arcanum initiates Operation Void Dominance. (Location: Void Echo Chasm, Scholar Elara) All void signatures must be catalogued, contained, or eliminated. Knowledge of the void must be total.', '{"npc_id": "npc_arcanum_scholar", "name": "Scholar Elara", "location": "VOID_ECHO_CHASM"}'::jsonb, '{"min_level": 51, "reputation_required": 3000, "required_quests": ["fq_arc_051"]}'::jsonb, '[{"type": "kill", "target": "VOID_REAVER", "count": 8, "description": "Catalog and eliminate Void Reavers."}, {"type": "kill", "target": "AETHEL_VOID_CHANNELER", "count": 5, "description": "Silence all remaining Void Channelers. [Aethel Void Channeler]"}]'::jsonb, '{"exp": 4500, "currency": 2200, "crd": 1100, "rep": 1500, "items": [{"item_id": "void_core", "quantity": 3}], "reputation": 50}'::jsonb, false, false, 'fq_arc_053', false, NULL, NULL, NULL, 'quest_arcanum.json', 51)
