values ('fq_arc_053', 'Stalker of Secrets', 'boss', 'S', 'THE_ARCANUM_SEEKERS', 'VOID_ECHO_CHASM', 'A Void Stalker has been hunting Arcanum researchers. (Location: Void Echo Chasm, Scholar Elara) It seems to be drawn to those who carry Precursor knowledge. Turn the hunt around.', '{"npc_id": "npc_arcanum_scholar", "name": "Scholar Elara", "location": "VOID_ECHO_CHASM"}'::jsonb, '{"min_level": 52, "reputation_required": 3060, "required_quests": ["fq_arc_052"]}'::jsonb, '[{"type": "kill", "target": "VOID_STALKER", "count": 1, "description": "Track and defeat the Void Stalker."}, {"type": "collect", "target": "monster_material", "count": 1, "description": "Collect monster material (x1). [Item: Monster Material]"}]'::jsonb, '{"exp": 5500, "currency": 2800, "crd": 1400, "rep": 1800, "items": [{"item_id": "entropy_core", "quantity": 1}], "reputation": 50}'::jsonb, false, false, 'fq_arc_054', false, NULL, NULL, NULL, 'quest_arcanum.json', 52)
