values ('fq_arc_054', 'Temporal Paradox', 'boss', 'S', 'THE_ARCANUM_SEEKERS', 'VOID_ECHO_CHASM', 'Chrono Wraiths are creating temporal loops within the chasm. (Location: Void Echo Chasm, Researcher Vin) Each loop traps a piece of Precursor knowledge in an endless cycle. Break the loops.', '{"npc_id": "npc_researcher_vin", "name": "Researcher Vin", "location": "VOID_ECHO_CHASM"}'::jsonb, '{"min_level": 53, "reputation_required": 3120, "required_quests": ["fq_arc_053"]}'::jsonb, '[{"type": "kill", "target": "CHRONO_WRAITH", "count": 2, "description": "Banish Chrono Wraiths from the temporal loops."}, {"type": "collect", "target": "core_fragment", "count": 2, "description": "Collect core fragment (x2). [Item: Core Fragment]"}]'::jsonb, '{"exp": 6500, "currency": 3200, "crd": 1600, "rep": 2000, "items": [{"item_id": "quantum_distortion_stone", "quantity": 2}], "reputation": 50}'::jsonb, false, false, 'fq_arc_055', false, NULL, NULL, NULL, 'quest_arcanum.json', 53)
