values ('fq_arc_055', 'Reaver Overflow', 'hunt', 'S', 'THE_ARCANUM_SEEKERS', 'SHATTERED_HEART', 'Abyssal Reavers flood from the Shattered Heart. Each one carries traces of Precursor data. The Arcanum must collect them all. Quest giver: Archivist Sylas at Observatory Spire Archive.', '{"npc_id": "npc_arcanum_archivist", "name": "Archivist Sylas", "location": "SHATTERED_HEART"}'::jsonb, '{"min_level": 54, "reputation_required": 3180, "required_quests": ["fq_arc_054"]}'::jsonb, '[{"type": "kill", "target": "AETHEL_ABYSSAL_REAVER", "count": 10, "description": "Defeat Abyssal Reavers and extract data traces. [Aethel Abyssal Reaver]"}, {"type": "collect", "target": "raw_aethel_fragment", "count": 1, "description": "Collect raw aethel fragment (x1). [Item: Raw Aethel Fragment]"}]'::jsonb, '{"exp": 5000, "currency": 2500, "crd": 1250, "rep": 1700, "items": [{"item_id": "event_horizon_fragment", "quantity": 3}], "reputation": 50}'::jsonb, false, false, 'fq_arc_056', false, NULL, NULL, NULL, 'quest_arcanum.json', 54)
