values ('fq_arc_056', 'Jotunn Archive Guardians', 'boss', 'S', 'THE_ARCANUM_SEEKERS', 'SHATTERED_HEART', 'Gigantic Jotunns in the Shattered Heart are not random — they guard something. The Arcanum believes a Precursor archive lies beneath their territory. Quest giver: Scholar Elara at Observatory Spire Research Wing.', '{"npc_id": "npc_arcanum_scholar", "name": "Scholar Elara", "location": "SHATTERED_HEART"}'::jsonb, '{"min_level": 55, "reputation_required": 3240, "required_quests": ["fq_arc_055"]}'::jsonb, '[{"type": "kill", "target": "GIGANTIC_JOTUNN", "count": 3, "description": "Defeat Jotunn archive guardians. [Gigantic Jotunn]"}, {"type": "collect", "target": "core_fragment", "count": 1, "description": "Collect core fragment (x1). [Item: Core Fragment]"}]'::jsonb, '{"exp": 7000, "currency": 3500, "crd": 1750, "rep": 2200, "items": [{"item_id": "titan_core", "quantity": 2}], "reputation": 50}'::jsonb, false, false, 'fq_arc_057', false, NULL, NULL, NULL, 'quest_arcanum.json', 55)
