values ('fq_arc_057', 'Tyrant Archive', 'boss', 'S', 'THE_ARCANUM_SEEKERS', 'SHATTERED_HEART', 'Crystal Tyrants have claimed the Precursor archive as their territory. (Location: Shattered Heart, Scholar Elara) Their crystalline bodies have absorbed millennia of stored knowledge.', '{"npc_id": "npc_arcanum_scholar", "name": "Scholar Elara", "location": "SHATTERED_HEART"}'::jsonb, '{"min_level": 56, "reputation_required": 3300, "required_quests": ["fq_arc_056"]}'::jsonb, '[{"type": "kill", "target": "CRYSTAL_TYRANT", "count": 2, "description": "Defeat Crystal Tyrants at the Precursor archive."}, {"type": "collect", "target": "monster_material", "count": 1, "description": "Collect monster material (x1). [Item: Monster Material]"}]'::jsonb, '{"exp": 7200, "currency": 3600, "crd": 1800, "rep": 2300, "items": [{"item_id": "cognitive_relay_node", "quantity": 2}], "reputation": 50}'::jsonb, false, false, 'fq_arc_058', false, NULL, NULL, NULL, 'quest_arcanum.json', 56)
