values ('fq_arc_058', 'The Harbinger''s Formula', 'story', 'S', 'THE_ARCANUM_SEEKERS', 'VOID_ECHO_CHASM', 'The Abyss Harbinger is not just a monster — it is a living formula. (Location: Void Echo Chasm, Scholar Elara) An equation of pure void given form. The Arcanum must record it before destroying it.', '{"npc_id": "npc_arcanum_scholar", "name": "Scholar Elara", "location": "VOID_ECHO_CHASM"}'::jsonb, '{"min_level": 57, "reputation_required": 230, "required_quests": ["fq_arc_057"]}'::jsonb, '[{"type": "kill", "target": "AETHEL_ABYSSAL_REAVER", "count": 6, "description": "Cut through the Harbinger''s vanguard. [Aethel Abyssal Reaver]"}, {"type": "kill", "target": "CHRONO_WRAITH", "count": 1, "description": "Defeat a Chrono Wraith to access the sanctum."}, {"type": "collect", "target": "raw_aethel_fragment", "count": 1, "description": "Collect raw aethel fragment (x1). [Item: Raw Aethel Fragment]"}]'::jsonb, '{"exp": 7500, "currency": 3800, "crd": 1900, "rep": 2400, "items": [{"item_id": "event_horizon_fragment_l", "quantity": 1}], "reputation": 50}'::jsonb, false, false, 'fq_arc_059', false, NULL, NULL, NULL, 'quest_arcanum.json', 57)
