values ('fq_arc_059', 'Soul Harvest', 'boss', 'S', 'THE_ARCANUM_SEEKERS', 'VOID_ECHO_CHASM', 'Soul Fragmenters are harvesting the souls of fallen researchers. (Location: Void Echo Chasm, Scholar Elara) The Arcanum cannot allow the accumulated knowledge of its members to be consumed.', '{"npc_id": "npc_arcanum_scholar", "name": "Scholar Elara", "location": "VOID_ECHO_CHASM"}'::jsonb, '{"min_level": 58, "reputation_required": 3420, "required_quests": ["fq_arc_058"]}'::jsonb, '[{"type": "kill", "target": "SOUL_FRAGMENTER", "count": 3, "description": "Destroy Soul Fragmenters to free trapped souls."}, {"type": "kill", "target": "VOID_STALKER", "count": 1, "description": "Eliminate the Void Stalker directing the Fragmenters."}]'::jsonb, '{"exp": 8000, "currency": 4000, "crd": 2000, "rep": 2500, "items": [{"item_id": "brainwave_oscillator", "quantity": 2}], "reputation": 50}'::jsonb, false, false, 'fq_arc_060', false, NULL, NULL, NULL, 'quest_arcanum.json', 58)
