values ('fq_arc_061', 'Seismic Research', 'exploration', 'S', 'THE_ARCANUM_SEEKERS', 'SEVERANCE_FAULTLINE', 'The Harbinger''s defeat has triggered unprecedented seismic activity. (Location: Severance Faultline, Researcher Vin) The Arcanum sees opportunity: tectonic data may reveal the planet''s deepest secrets.', '{"npc_id": "npc_researcher_vin", "name": "Researcher Vin", "location": "SEVERANCE_FAULTLINE"}'::jsonb, '{"min_level": 60, "reputation_required": 3540, "required_quests": ["fq_arc_060"]}'::jsonb, '[{"type": "travel", "target": "SEVERANCE_FAULTLINE", "count": 1, "description": "Enter the Severance Faultline."}, {"type": "collect", "target": "monster_material", "count": 3, "description": "Collect monster material (x3). [Item: Monster Material]"}]'::jsonb, '{"exp": 5000, "currency": 2500, "crd": 1250, "rep": 1600, "items": [{"item_id": "stabilizer_gyro_unit", "quantity": 2}], "reputation": 50}'::jsonb, false, false, 'fq_arc_062', false, NULL, NULL, NULL, 'quest_arcanum.json', 60)
