values ('fq_arc_062', 'Tectonic Scanning', 'hunt', 'S', 'THE_ARCANUM_SEEKERS', 'SEVERANCE_FAULTLINE', 'Aethel Iron Carapaces are drawn to the fault''s energy. (Location: Severance Faultline, Researcher Vin) Their shells contain compressed geological data spanning millions of years.', '{"npc_id": "npc_researcher_vin", "name": "Researcher Vin", "location": "SEVERANCE_FAULTLINE"}'::jsonb, '{"min_level": 61, "reputation_required": 3600, "required_quests": ["fq_arc_061"]}'::jsonb, '[{"type": "kill", "target": "AETHEL_IRON_CARAPACE", "count": 8, "description": "Defeat Iron Carapaces for geological data. [Aethel Iron Carapace]"}, {"type": "collect", "target": "crystal_core", "count": 3, "description": "Collect crystal core (x3). [Item: Crystal Core]"}]'::jsonb, '{"exp": 5200, "currency": 2600, "crd": 1300, "rep": 1700, "items": [{"item_id": "gravity_well_core", "quantity": 1}], "reputation": 50}'::jsonb, false, false, 'fq_arc_063', false, NULL, NULL, NULL, 'quest_arcanum.json', 61)
