values ('fq_arc_063', 'Tyrant Seismic', 'boss', 'S', 'THE_ARCANUM_SEEKERS', 'SEVERANCE_FAULTLINE', 'Crystal Tyrants at the fault emit resonant frequencies that amplify seismic waves. (Location: Severance Faultline, Scholar Elara) The Arcanum hypothesizes they can be used as planetary-scale transmitters.', '{"npc_id": "npc_arcanum_scholar", "name": "Scholar Elara", "location": "SEVERANCE_FAULTLINE"}'::jsonb, '{"min_level": 62, "reputation_required": 3660, "required_quests": ["fq_arc_062"]}'::jsonb, '[{"type": "kill", "target": "CRYSTAL_TYRANT", "count": 2, "description": "Defeat Crystal Tyrants for resonance study."}, {"type": "collect", "target": "core_fragment", "count": 1, "description": "Collect core fragment (x1). [Item: Core Fragment]"}]'::jsonb, '{"exp": 6000, "currency": 3000, "crd": 1500, "rep": 2000, "items": [{"item_id": "quantum_distortion_stone", "quantity": 2}], "reputation": 50}'::jsonb, false, false, 'fq_arc_064', false, NULL, NULL, NULL, 'quest_arcanum.json', 62)
