values ('fq_arc_064', 'Jotunn Migration', 'boss', 'S', 'THE_ARCANUM_SEEKERS', 'SEVERANCE_FAULTLINE', 'Gigantic Jotunns are migrating through the faultline. (Location: Severance Faultline, Scholar Elara) Their movement patterns correlate with Precursor navigation charts discovered in the Harbinger''s archives.', '{"npc_id": "npc_arcanum_scholar", "name": "Scholar Elara", "location": "SEVERANCE_FAULTLINE"}'::jsonb, '{"min_level": 63, "reputation_required": 3720, "required_quests": ["fq_arc_063"]}'::jsonb, '[{"type": "kill", "target": "GIGANTIC_JOTUNN", "count": 3, "description": "Defeat migrating Jotunns. [Gigantic Jotunn]"}, {"type": "collect", "target": "monster_material", "count": 1, "description": "Collect monster material (x1). [Item: Monster Material]"}]'::jsonb, '{"exp": 6500, "currency": 3300, "crd": 1650, "rep": 2100, "items": [{"item_id": "titan_core", "quantity": 2}], "reputation": 50}'::jsonb, false, false, 'fq_arc_065', false, NULL, NULL, NULL, 'quest_arcanum.json', 63)
