values ('fq_arc_065', 'The Siphon Laboratory', 'exploration', 'S', 'THE_ARCANUM_SEEKERS', 'AETHEL_SIPHON_CORE', 'The Aethel Siphon Core is the ultimate Precursor laboratory. The Arcanum has theorized its existence for centuries. Now it is discovered — claim it for science. Quest giver: Scholar Elara at Observatory Spire Research Wing.', '{"npc_id": "npc_arcanum_scholar", "name": "Scholar Elara", "location": "AETHEL_SIPHON_CORE"}'::jsonb, '{"min_level": 64, "reputation_required": 3780, "required_quests": ["fq_arc_064"]}'::jsonb, '[{"type": "travel", "target": "AETHEL_SIPHON_CORE", "count": 1, "description": "Enter the Aethel Siphon Core."}, {"type": "collect", "target": "monster_material", "count": 2, "description": "Collect monster material (x2). [Item: Monster Material]"}]'::jsonb, '{"exp": 5500, "currency": 2800, "crd": 1400, "rep": 1800, "items": [{"item_id": "power_regulator_core", "quantity": 1}], "reputation": 50}'::jsonb, false, false, 'fq_arc_066', false, NULL, NULL, NULL, 'quest_arcanum.json', 64)
