values ('fq_arc_066', 'Core Specimens', 'hunt', 'S', 'THE_ARCANUM_SEEKERS', 'AETHEL_SIPHON_CORE', 'Abyssal Reavers in the Core have been mutated by concentrated Aethel. (Location: Aethel Siphon Core, Researcher Vin) These mutations are scientifically invaluable.', '{"npc_id": "npc_researcher_vin", "name": "Researcher Vin", "location": "AETHEL_SIPHON_CORE"}'::jsonb, '{"min_level": 65, "reputation_required": 3840, "required_quests": ["fq_arc_065"]}'::jsonb, '[{"type": "kill", "target": "AETHEL_ABYSSAL_REAVER", "count": 8, "description": "Collect mutated Reaver specimens. [Aethel Abyssal Reaver]"}, {"type": "collect", "target": "abyssal_reaver_claw", "count": 1, "description": "Collect abyssal reaver claw (x1). [Item: Abyssal Reaver Claw]"}]'::jsonb, '{"exp": 5800, "currency": 2900, "crd": 1450, "rep": 1900, "items": [{"item_id": "aethel_core_shard", "quantity": 3}], "reputation": 50}'::jsonb, false, false, 'fq_arc_067', false, NULL, NULL, NULL, 'quest_arcanum.json', 65)
