values ('fq_arc_067', 'Behemoth Siege', 'boss', 'S', 'THE_ARCANUM_SEEKERS', 'AETHEL_SIPHON_CORE', 'Corrupted Behemoths assault the Core''s primary conduits. (Location: Aethel Siphon Core, Scholar Elara) If the Core falls, the greatest Precursor laboratory is lost forever.', '{"npc_id": "npc_arcanum_scholar", "name": "Scholar Elara", "location": "AETHEL_SIPHON_CORE"}'::jsonb, '{"min_level": 66, "reputation_required": 3900, "required_quests": ["fq_arc_066"]}'::jsonb, '[{"type": "kill", "target": "AETHEL_CORRUPTED_BEHEMOTH", "count": 3, "description": "Defeat Corrupted Behemoths at the conduits. [Aethel Corrupted Behemoth]"}, {"type": "collect", "target": "raw_aethel_fragment", "count": 1, "description": "Collect raw aethel fragment (x1). [Item: Raw Aethel Fragment]"}]'::jsonb, '{"exp": 6200, "currency": 3100, "crd": 1550, "rep": 2000, "items": [{"item_id": "corrupted_synapse_cluster", "quantity": 2}], "reputation": 50}'::jsonb, false, false, 'fq_arc_068', false, NULL, NULL, NULL, 'quest_arcanum.json', 66)
