values ('fq_arc_068', 'Rift Research', 'boss', 'S', 'THE_ARCANUM_SEEKERS', 'AETHEL_SIPHON_CORE', 'Aethel Rift Stalkers create micro-rifts that offer glimpses into alternate dimensions. (Location: Aethel Siphon Core, Researcher Vin) The Arcanum must study these windows into other realities.', '{"npc_id": "npc_researcher_vin", "name": "Researcher Vin", "location": "AETHEL_SIPHON_CORE"}'::jsonb, '{"min_level": 67, "reputation_required": 3960, "required_quests": ["fq_arc_067"]}'::jsonb, '[{"type": "kill", "target": "AETHEL_RIFT_STALKER", "count": 6, "description": "Defeat Rift Stalkers near active micro-rifts. [Aethel Rift Stalker]"}, {"type": "collect", "target": "raw_aethel_fragment", "count": 1, "description": "Collect raw aethel fragment (x1). [Item: Raw Aethel Fragment]"}]'::jsonb, '{"exp": 6400, "currency": 3200, "crd": 1600, "rep": 2100, "items": [{"item_id": "dark_energy_fragment", "quantity": 3}], "reputation": 50}'::jsonb, false, false, 'fq_arc_069', false, NULL, NULL, NULL, 'quest_arcanum.json', 67)
