values ('fq_arc_069', 'Titan''s Formula', 'story', 'S', 'THE_ARCANUM_SEEKERS', 'AETHEL_SIPHON_CORE', 'The Gravity Titan''s existence is a mathematical anomaly. (Location: Aethel Siphon Core, Scholar Elara) The Arcanum believes understanding its formula could revolutionize gravitational science.', '{"npc_id": "npc_arcanum_scholar", "name": "Scholar Elara", "location": "AETHEL_SIPHON_CORE"}'::jsonb, '{"min_level": 68, "reputation_required": 280, "required_quests": ["fq_arc_068"]}'::jsonb, '[{"type": "collect", "target": "core_fragment", "count": 3, "description": "Collect core fragment (x3). [Item: Core Fragment]"}, {"type": "kill", "target": "GIGANTIC_JOTUNN", "count": 1, "description": "Defeat a Jotunn drawn by Titan resonance. [Gigantic Jotunn]"}]'::jsonb, '{"exp": 7000, "currency": 3500, "crd": 1750, "rep": 2200, "items": [{"item_id": "gravity_well_core", "quantity": 2}], "reputation": 50}'::jsonb, false, false, 'fq_arc_070', false, NULL, NULL, NULL, 'quest_arcanum.json', 68)
