values ('fq_arc_071', 'The Great Forge', 'exploration', 'S', 'THE_ARCANUM_SEEKERS', 'PRIMA_MATERIA_FORGE', 'The Prima Materia Forge — the Precursor facility where reality itself can be shaped. The Arcanum''s ultimate ambition: master the Forge and create legendary weapons. Quest giver: Scholar Elara at Observatory Spire Research Wing.', '{"npc_id": "npc_arcanum_scholar", "name": "Scholar Elara", "location": "PRIMA_MATERIA_FORGE"}'::jsonb, '{"min_level": 70, "reputation_required": 4140, "required_quests": ["fq_arc_070"]}'::jsonb, '[{"type": "travel", "target": "PRIMA_MATERIA_FORGE", "count": 1, "description": "Enter the Prima Materia Forge."}, {"type": "collect", "target": "monster_material", "count": 2, "description": "Collect monster material (x2). [Item: Monster Material]"}]'::jsonb, '{"exp": 6000, "currency": 3000, "crd": 1500, "rep": 2000, "items": [{"item_id": "raw_aethel_core", "quantity": 2}], "reputation": 50}'::jsonb, false, false, 'fq_arc_072', false, NULL, NULL, NULL, 'quest_arcanum.json', 70)
