values ('fq_arc_072', 'Forge Defenses', 'hunt', 'S', 'THE_ARCANUM_SEEKERS', 'PRIMA_MATERIA_FORGE', 'Ancient Forge Automatons still defend the facility. (Location: Prima Materia Forge, Researcher Vin) Disable them and reverse-engineer their construction — the Arcanum could replicate this technology.', '{"npc_id": "npc_researcher_vin", "name": "Researcher Vin", "location": "PRIMA_MATERIA_FORGE"}'::jsonb, '{"min_level": 71, "reputation_required": 4200, "required_quests": ["fq_arc_071"]}'::jsonb, '[{"type": "kill", "target": "AETHEL_IRON_CARAPACE", "count": 8, "description": "Disable Forge defense automatons. [Aethel Iron Carapace]"}, {"type": "collect", "target": "crystal_core", "count": 2, "description": "Collect crystal core (x2). [Item: Crystal Core]"}]'::jsonb, '{"exp": 6200, "currency": 3100, "crd": 1550, "rep": 2100, "items": [{"item_id": "rusted_cybernetic_arm", "quantity": 2}], "reputation": 50}'::jsonb, false, false, 'fq_arc_073', false, NULL, NULL, NULL, 'quest_arcanum.json', 71)
