values ('fq_arc_073', 'Forge Purification', 'boss', 'S', 'THE_ARCANUM_SEEKERS', 'PRIMA_MATERIA_FORGE', 'Corrupted Behemoths contaminate the Forge''s raw materials. (Location: Prima Materia Forge, Scholar Elara) The purity of Prima Materia must be absolute for legendary crafting.', '{"npc_id": "npc_arcanum_scholar", "name": "Scholar Elara", "location": "PRIMA_MATERIA_FORGE"}'::jsonb, '{"min_level": 72, "reputation_required": 4260, "required_quests": ["fq_arc_072"]}'::jsonb, '[{"type": "kill", "target": "AETHEL_CORRUPTED_BEHEMOTH", "count": 3, "description": "Purge Corrupted Behemoths from the Forge. [Aethel Corrupted Behemoth]"}, {"type": "collect", "target": "raw_aethel_fragment", "count": 3, "description": "Collect raw aethel fragment (x3). [Item: Raw Aethel Fragment]"}]'::jsonb, '{"exp": 6500, "currency": 3300, "crd": 1650, "rep": 2200, "items": [{"item_id": "neural_disruptor_module", "quantity": 1}], "reputation": 50}'::jsonb, false, false, 'fq_arc_074', false, NULL, NULL, NULL, 'quest_arcanum.json', 72)
