values ('fq_arc_074', 'Abyssal Contamination', 'hunt', 'S', 'THE_ARCANUM_SEEKERS', 'PRIMA_MATERIA_FORGE', 'Void Channelers seek to corrupt the Forge. (Location: Prima Materia Forge, Scholar Elara) Void-tainted Prima Materia would be catastrophic. Stop them at all costs.', '{"npc_id": "npc_arcanum_scholar", "name": "Scholar Elara", "location": "PRIMA_MATERIA_FORGE"}'::jsonb, '{"min_level": 73, "reputation_required": 4320, "required_quests": ["fq_arc_073"]}'::jsonb, '[{"type": "kill", "target": "AETHEL_ABYSSAL_REAVER", "count": 8, "description": "Exterminate Abyssal Reavers. [Aethel Abyssal Reaver]"}, {"type": "kill", "target": "AETHEL_VOID_CHANNELER", "count": 5, "description": "Silence Void Channelers at the Forge core. [Aethel Void Channeler]"}]'::jsonb, '{"exp": 6800, "currency": 3400, "crd": 1700, "rep": 2300, "items": [{"item_id": "aethel_fragment", "quantity": 3}], "reputation": 50}'::jsonb, false, false, 'fq_arc_075', false, NULL, NULL, NULL, 'quest_arcanum.json', 73)
