values ('fq_arc_075', 'Jotunn Forge-Masters', 'boss', 'S', 'THE_ARCANUM_SEEKERS', 'PRIMA_MATERIA_FORGE', 'Gigantic Jotunns have learned to use the Forge''s heat as a weapon. (Location: Prima Materia Forge, Researcher Vin) Their mastery of the Forge''s fire is concerning — and fascinating.', '{"npc_id": "npc_researcher_vin", "name": "Researcher Vin", "location": "PRIMA_MATERIA_FORGE"}'::jsonb, '{"min_level": 74, "reputation_required": 4380, "required_quests": ["fq_arc_074"]}'::jsonb, '[{"type": "kill", "target": "GIGANTIC_JOTUNN", "count": 3, "description": "Defeat Jotunn Forge-Masters. [Gigantic Jotunn]"}, {"type": "collect", "target": "monster_material", "count": 1, "description": "Collect monster material (x1). [Item: Monster Material]"}]'::jsonb, '{"exp": 7200, "currency": 3600, "crd": 1800, "rep": 2400, "items": [{"item_id": "titan_core", "quantity": 2}], "reputation": 50}'::jsonb, false, false, 'fq_arc_076', false, NULL, NULL, NULL, 'quest_arcanum.json', 74)
