values ('fq_arc_076', 'Materia Synthesis', 'hunt', 'S', 'THE_ARCANUM_SEEKERS', 'PRIMA_MATERIA_FORGE', 'The Arcanum initiates Operation Materia Synthesis. (Location: Prima Materia Forge, Scholar Elara) The goal: produce the first Arcanum-crafted legendary weapon using Prima Materia.', '{"npc_id": "npc_arcanum_scholar", "name": "Scholar Elara", "location": "PRIMA_MATERIA_FORGE"}'::jsonb, '{"min_level": 75, "reputation_required": 4440, "required_quests": ["fq_arc_075"]}'::jsonb, '[{"type": "kill", "target": "AETHEL_VOID_CHANNELER", "count": 6, "description": "Clear the Forge of hostile forces. [Aethel Void Channeler]"}, {"type": "collect", "target": "void_channeler_core", "count": 3, "description": "Collect void channeler core (x3). [Item: Void Channeler Core]"}]'::jsonb, '{"exp": 7500, "currency": 3800, "crd": 1900, "rep": 2500, "items": [{"item_id": "power_regulator_core", "quantity": 2}], "reputation": 50}'::jsonb, false, false, 'fq_arc_077', false, NULL, NULL, NULL, 'quest_arcanum.json', 75)
