values ('fq_arc_077', 'Automaton Mastery', 'boss', 'S', 'THE_ARCANUM_SEEKERS', 'PRIMA_MATERIA_FORGE', 'Titan Forge Automatons are the apex of Precursor engineering. (Location: Prima Materia Forge, Researcher Vin) The Arcanum must learn to control them rather than simply destroy them.', '{"npc_id": "npc_researcher_vin", "name": "Researcher Vin", "location": "PRIMA_MATERIA_FORGE"}'::jsonb, '{"min_level": 76, "reputation_required": 4500, "required_quests": ["fq_arc_076"]}'::jsonb, '[{"type": "kill", "target": "TITAN_FORGE_AUTOMATON", "count": 2, "description": "Override Titan Forge Automatons."}, {"type": "collect", "target": "core_fragment", "count": 1, "description": "Collect core fragment (x1). [Item: Core Fragment]"}]'::jsonb, '{"exp": 8000, "currency": 4000, "crd": 2000, "rep": 2600, "items": [{"item_id": "processor_cooling_unit", "quantity": 2}], "reputation": 50}'::jsonb, false, false, 'fq_arc_078', false, NULL, NULL, NULL, 'quest_arcanum.json', 76)
