values ('fq_arc_078', 'Proto-Core Experiment', 'boss', 'S', 'THE_ARCANUM_SEEKERS', 'PRIMA_MATERIA_FORGE', 'A Titan Proto Core contains a failed Titan — the ultimate experimental subject. (Location: Prima Materia Forge, Researcher Vin) The Arcanum must dissect it to understand Titan biology.', '{"npc_id": "npc_researcher_vin", "name": "Researcher Vin", "location": "PRIMA_MATERIA_FORGE"}'::jsonb, '{"min_level": 77, "reputation_required": 4560, "required_quests": ["fq_arc_077"]}'::jsonb, '[{"type": "kill", "target": "TITAN_PROTO_CORE", "count": 1, "description": "Destroy the Titan Proto Core for dissection."}, {"type": "collect", "target": "titan_core", "count": 1, "description": "Collect titan core (x1). [Item: Titan Core]"}]'::jsonb, '{"exp": 9000, "currency": 4500, "crd": 2250, "rep": 2800, "items": [{"item_id": "titan_core", "quantity": 2}], "reputation": 50}'::jsonb, false, false, 'fq_arc_079', false, NULL, NULL, NULL, 'quest_arcanum.json', 77)
