values ('fq_arc_079', 'The Forge Complete', 'story', 'S', 'THE_ARCANUM_SEEKERS', 'PRIMA_MATERIA_FORGE', 'The Forge is mastered. (Location: Prima Materia Forge, Scholar Elara) The legendary weapon is forged. But the final test remains: prove the weapon''s worth against the two greatest threats to Xylos.', '{"npc_id": "npc_arcanum_scholar", "name": "Scholar Elara", "location": "PRIMA_MATERIA_FORGE"}'::jsonb, '{"min_level": 78, "reputation_required": 330, "required_quests": ["fq_arc_078"]}'::jsonb, '[{"type": "kill", "target": "GRAVITY_TITAN", "count": 1, "description": "Test the legendary weapon against the Gravity Titan."}, {"type": "kill", "target": "ABYSS_HARBINGER", "count": 1, "description": "Prove the weapon''s worth against the Abyss Harbinger."}]'::jsonb, '{"exp": 12000, "currency": 6000, "crd": 3000, "rep": 4000, "items": [{"item_id": "drake_heart", "quantity": 1}, {"item_id": "titan_core", "quantity": 2}, {"item_id": "void_core", "quantity": 3}], "reputation": 50}'::jsonb, false, false, 'fq_arc_080', false, NULL, NULL, NULL, 'quest_arcanum.json', 78)
