values ('fq_arc_080', 'Legendary Seeker', 'story', 'S', 'THE_ARCANUM_SEEKERS', 'OBSERVATORY_SPIRE', 'You have defeated both Titan and Harbinger in a single campaign. The Arcanum Seekers recognize you as a Legendary Seeker. Return to the Observatory Spire. Quest giver: Scholar Elara at Observatory Spire Research Wing.', '{"npc_id": "npc_arcanum_scholar", "name": "Scholar Elara", "location": "OBSERVATORY_SPIRE"}'::jsonb, '{"min_level": 79, "reputation_required": 380, "required_quests": ["fq_arc_079"]}'::jsonb, '[{"type": "travel", "target": "OBSERVATORY_SPIRE", "count": 1, "description": "Return to the Observatory Spire."}, {"type": "collect", "target": "desert_chitin", "count": 1, "description": "Collect desert chitin (x1). [Item: Desert Chitin]"}]'::jsonb, '{"exp": 10000, "currency": 5000, "crd": 2500, "rep": 3500, "items": [{"item_id": "con_elite_recovery_pack", "quantity": 10}, {"item_id": "astral_phase_crystal_pure", "quantity": 3}], "reputation": 50}'::jsonb, false, false, 'fq_arc_081', false, NULL, NULL, NULL, 'quest_arcanum.json', 79)
