values ('fq_arc_081', 'Apex Dominance', 'story', 'S', 'THE_ARCANUM_SEEKERS', 'HIDDEN_AETHELGARDIAN_CITY', 'The Hidden Aethelgardian City — a mythical Precursor metropolis. The Arcanum has triangulated its location using data from the Titan and Harbinger. Enter and claim its knowledge. Quest giver: Scholar Elara at Observatory Spire Research Wing.', '{"npc_id": "npc_arcanum_scholar", "name": "Scholar Elara", "location": "HIDDEN_AETHELGARDIAN_CITY"}'::jsonb, '{"min_level": 80, "reputation_required": 430, "required_quests": ["fq_arc_080"]}'::jsonb, '[{"type": "travel", "target": "HIDDEN_AETHELGARDIAN_CITY", "count": 1, "description": "Discover the Hidden Aethelgardian City."}, {"type": "collect", "target": "desert_chitin", "count": 3, "description": "Collect desert chitin (x3). [Item: Desert Chitin]"}]'::jsonb, '{"exp": 8000, "currency": 4000, "crd": 2000, "rep": 2500, "items": [{"item_id": "aethel_core_shard", "quantity": 5}], "reputation": 50}'::jsonb, false, false, 'fq_arc_082', false, NULL, NULL, NULL, 'quest_arcanum.json', 80)
