values ('fq_arc_082', 'City Defenses', 'hunt', 'S', 'THE_ARCANUM_SEEKERS', 'HIDDEN_AETHELGARDIAN_CITY', 'The city''s automated defenses still function. (Location: Hidden Aethelgardian City, Researcher Vin) They do not distinguish between friend and foe — only threats to Precursor knowledge.', '{"npc_id": "npc_researcher_vin", "name": "Researcher Vin", "location": "HIDDEN_AETHELGARDIAN_CITY"}'::jsonb, '{"min_level": 81, "reputation_required": 4800, "required_quests": ["fq_arc_081"]}'::jsonb, '[{"type": "kill", "target": "AETHEL_RIFT_STALKER", "count": 8, "description": "Disable city defense constructs. [Aethel Rift Stalker]"}, {"type": "collect", "target": "raw_aethel_fragment", "count": 1, "description": "Collect raw aethel fragment (x1). [Item: Raw Aethel Fragment]"}]'::jsonb, '{"exp": 8500, "currency": 4200, "crd": 2100, "rep": 2700, "items": [{"item_id": "quantum_distortion_stone", "quantity": 2}], "reputation": 50}'::jsonb, false, false, 'fq_arc_083', false, NULL, NULL, NULL, 'quest_arcanum.json', 81)
