values ('fq_arc_083', 'The Eternal Library', 'collect', 'S', 'THE_ARCANUM_SEEKERS', 'HIDDEN_AETHELGARDIAN_CITY', 'The city contains the Eternal Library — a Precursor repository of all knowledge. (Location: Hidden Aethelgardian City, Archivist Sylas) Download its contents for the Arcanum''s grand archive.', '{"npc_id": "npc_arcanum_archivist", "name": "Archivist Sylas", "location": "HIDDEN_AETHELGARDIAN_CITY"}'::jsonb, '{"min_level": 82, "reputation_required": 4860, "required_quests": ["fq_arc_082"]}'::jsonb, '[{"type": "collect", "target": "abyssal_reaver_claw", "count": 5, "description": "Collect abyssal reaver claw (x5). [Item: Abyssal Reaver Claw]"}, {"type": "kill", "target": "AETHEL_ABYSSAL_REAVER", "count": 4, "description": "Defeat Reavers drawn to the knowledge energy. [Aethel Abyssal Reaver]"}]'::jsonb, '{"exp": 8800, "currency": 4400, "crd": 2200, "rep": 2800, "items": [{"item_id": "memory_fragment_chip", "quantity": 5}], "reputation": 50}'::jsonb, false, false, 'fq_arc_084', false, NULL, NULL, NULL, 'quest_arcanum.json', 82)
