values ('fq_arc_084', 'Apex Drake', 'boss', 'S', 'THE_ARCANUM_SEEKERS', 'SHATTERED_HEART', 'The Ashen Drake has evolved to its Apex form — a living repository of draconic knowledge. (Location: Shattered Heart, Scholar Elara) The Arcanum must study this ultimate form.', '{"npc_id": "npc_arcanum_scholar", "name": "Scholar Elara", "location": "SHATTERED_HEART"}'::jsonb, '{"min_level": 83, "reputation_required": 4920, "required_quests": ["fq_arc_083"]}'::jsonb, '[{"type": "kill", "target": "ASHEN_DRAKE", "count": 1, "description": "Defeat the Apex Ashen Drake."}, {"type": "collect", "target": "ancient_scale", "count": 1, "description": "Collect ancient scale (x1). [Item: Ancient Scale]"}]'::jsonb, '{"exp": 12000, "currency": 6000, "crd": 3000, "rep": 4000, "items": [{"item_id": "drake_heart", "quantity": 3}, {"item_id": "ancient_scale", "quantity": 3}], "reputation": 50}'::jsonb, false, false, 'fq_arc_085', false, NULL, NULL, NULL, 'quest_arcanum.json', 83)
