values ('fq_arc_085', 'Apex Harbinger', 'boss', 'S', 'THE_ARCANUM_SEEKERS', 'VOID_ECHO_CHASM', 'The Abyss Harbinger''s rebirth brings new void-knowledge. (Location: Void Echo Chasm, Scholar Elara) The Arcanum must record its new form before destroying it forever.', '{"npc_id": "npc_arcanum_scholar", "name": "Scholar Elara", "location": "VOID_ECHO_CHASM"}'::jsonb, '{"min_level": 84, "reputation_required": 4980, "required_quests": ["fq_arc_084"]}'::jsonb, '[{"type": "kill", "target": "ABYSS_HARBINGER", "count": 1, "description": "Defeat the Apex Abyss Harbinger."}, {"type": "collect", "target": "void_core", "count": 1, "description": "Collect void core (x1). [Item: Void Core]"}]'::jsonb, '{"exp": 13000, "currency": 6500, "crd": 3250, "rep": 4200, "items": [{"item_id": "void_core", "quantity": 5}, {"item_id": "event_horizon_fragment_l", "quantity": 3}], "reputation": 50}'::jsonb, false, false, 'fq_arc_086', false, NULL, NULL, NULL, 'quest_arcanum.json', 84)
