values ('fq_arc_086', 'Apex Titan', 'boss', 'S', 'THE_ARCANUM_SEEKERS', 'CRADLE_EXPANSE', 'The Gravity Titan''s third manifestation is its most powerful. (Location: Cradle Expanse, Scholar Elara) Its gravitational signature contains data from the planet''s formation. The Arcanum must have it.', '{"npc_id": "npc_arcanum_scholar", "name": "Scholar Elara", "location": "CRADLE_EXPANSE"}'::jsonb, '{"min_level": 85, "reputation_required": 5040, "required_quests": ["fq_arc_085"]}'::jsonb, '[{"type": "kill", "target": "GRAVITY_TITAN", "count": 1, "description": "Defeat the Apex Gravity Titan."}, {"type": "collect", "target": "monster_material", "count": 1, "description": "Collect monster material (x1). [Item: Monster Material]"}]'::jsonb, '{"exp": 14000, "currency": 7000, "crd": 3500, "rep": 4500, "items": [{"item_id": "titan_core", "quantity": 4}, {"item_id": "gravity_well_core", "quantity": 3}], "reputation": 50}'::jsonb, false, false, 'fq_arc_087', false, NULL, NULL, NULL, 'quest_arcanum.json', 85)
