values ('fq_arc_087', 'Tri-Entity Research', 'boss', 'S', 'THE_ARCANUM_SEEKERS', 'PRIMA_MATERIA_FORGE', 'The three Apex entities — Drake, Titan, Harbinger — represent three branches of forbidden knowledge. (Location: Prima Materia Forge, Scholar Elara) The Arcanum authorizes their simultaneous study.', '{"npc_id": "npc_arcanum_scholar", "name": "Scholar Elara", "location": "PRIMA_MATERIA_FORGE"}'::jsonb, '{"min_level": 86, "reputation_required": 5100, "required_quests": ["fq_arc_086"]}'::jsonb, '[{"type": "kill", "target": "ASHEN_DRAKE", "count": 1, "description": "Study the Drake manifestation. [Ashen Drake]"}, {"type": "kill", "target": "GRAVITY_TITAN", "count": 1, "description": "Study the Titan manifestation. [Gravity Titan]"}, {"type": "kill", "target": "ABYSS_HARBINGER", "count": 1, "description": "Study the Harbinger manifestation. [Abyss Harbinger]"}]'::jsonb, '{"exp": 20000, "currency": 10000, "crd": 5000, "rep": 6000, "items": [{"item_id": "drake_heart", "quantity": 2}, {"item_id": "titan_core", "quantity": 2}, {"item_id": "void_core", "quantity": 3}], "reputation": 50}'::jsonb, false, false, 'fq_arc_088', false, NULL, NULL, NULL, 'quest_arcanum.json', 86)
