values ('fq_arc_088', 'The Siphon Overlord', 'exploration', 'S', 'THE_ARCANUM_SEEKERS', 'AETHEL_SIPHON_CORE', 'The Aethel Siphon Core is now the Arcanum''s primary research facility. Establish total control and begin the planetary energy calibration. Quest giver: Scholar Elara at Observatory Spire Research Wing.', '{"npc_id": "npc_arcanum_scholar", "name": "Scholar Elara", "location": "AETHEL_SIPHON_CORE"}'::jsonb, '{"min_level": 87, "reputation_required": 5160, "required_quests": ["fq_arc_087"]}'::jsonb, '[{"type": "travel", "target": "AETHEL_SIPHON_CORE", "count": 1, "description": "Return to the Siphon Core as Overlord. (Travel to: Aethel Siphon Core, Shattered Heart)"}, {"type": "collect", "target": "raw_aethel_fragment", "count": 5, "description": "Collect raw aethel fragment (x5). [Item: Raw Aethel Fragment]"}]'::jsonb, '{"exp": 10000, "currency": 5000, "crd": 2500, "rep": 3200, "items": [{"item_id": "power_regulator_core", "quantity": 3}], "reputation": 50}'::jsonb, false, false, 'fq_arc_089', false, NULL, NULL, NULL, 'quest_arcanum.json', 87)
