values ('fq_arc_089', 'World Engine Discovery', 'story', 'S', 'THE_ARCANUM_SEEKERS', 'AETHEL_SIPHON_CORE', 'Beneath the Siphon Core lies the World Engine — the device that can reshape planetary reality. (Location: Aethel Siphon Core, Scholar Elara) The Arcanum''s greatest discovery. Secure it absolutely.', '{"npc_id": "npc_arcanum_scholar", "name": "Scholar Elara", "location": "AETHEL_SIPHON_CORE"}'::jsonb, '{"min_level": 88, "reputation_required": 480, "required_quests": ["fq_arc_088"]}'::jsonb, '[{"type": "collect", "target": "monster_material", "count": 3, "description": "Collect monster material (x3). [Item: Monster Material]"}, {"type": "kill", "target": "GIGANTIC_JOTUNN", "count": 2, "description": "Defeat Jotunns guarding the Engine. [Gigantic Jotunn]"}]'::jsonb, '{"exp": 11000, "currency": 5500, "crd": 2750, "rep": 3500, "items": [{"item_id": "aethel_core_shard", "quantity": 5}], "reputation": 50}'::jsonb, false, false, 'fq_arc_090', false, NULL, NULL, NULL, 'quest_arcanum.json', 88)
