values ('fq_arc_090', 'Knowledge Calibration', 'story', 'S', 'THE_ARCANUM_SEEKERS', 'AETHEL_SIPHON_CORE', 'The World Engine can be calibrated to broadcast knowledge across the planet. (Location: Aethel Siphon Core, Scholar Elara) The Arcanum''s ultimate dream: a world where all knowledge is shared. Protect the calibration.', '{"npc_id": "npc_arcanum_scholar", "name": "Scholar Elara", "location": "AETHEL_SIPHON_CORE"}'::jsonb, '{"min_level": 89, "reputation_required": 530, "required_quests": ["fq_arc_089"]}'::jsonb, '[{"type": "kill", "target": "AETHEL_ABYSSAL_REAVER", "count": 10, "description": "Defend the World Engine from Abyssal assault. [Aethel Abyssal Reaver]"}, {"type": "kill", "target": "CRYSTAL_TYRANT", "count": 2, "description": "Defeat Tyrants disrupting the calibration. [Crystal Tyrant]"}, {"type": "collect", "target": "abyssal_reaver_claw", "count": 1, "description": "Collect abyssal reaver claw (x1). [Item: Abyssal Reaver Claw]"}]'::jsonb, '{"exp": 13000, "currency": 6500, "crd": 3250, "rep": 4200, "items": [{"item_id": "resonanted_astral_phase_crystal", "quantity": 1}], "reputation": 50}'::jsonb, false, false, 'fq_arc_091', false, NULL, NULL, NULL, 'quest_arcanum.json', 89)
