values ('fq_arc_091', 'Jotunn Purge', 'hunt', 'S', 'THE_ARCANUM_SEEKERS', 'SEVERANCE_FAULTLINE', 'Residual hostile entities are being flushed by the World Engine. Begin the systematic purge at the Severance Faultline. Quest giver: Scholar Elara at Observatory Spire Research Wing.', '{"npc_id": "npc_arcanum_scholar", "name": "Scholar Elara", "location": "SEVERANCE_FAULTLINE"}'::jsonb, '{"min_level": 90, "reputation_required": 5340, "required_quests": ["fq_arc_090"]}'::jsonb, '[{"type": "kill", "target": "GIGANTIC_JOTUNN", "count": 5, "description": "Purge Jotunns from the faultline. [Gigantic Jotunn]"}, {"type": "kill", "target": "AETHEL_IRON_CARAPACE", "count": 8, "description": "Eliminate Carapace swarms. [Aethel Iron Carapace]"}]'::jsonb, '{"exp": 10000, "currency": 5000, "crd": 2500, "rep": 3200, "items": [{"item_id": "stabilizer_gyro_unit", "quantity": 3}], "reputation": 50}'::jsonb, false, false, 'fq_arc_092', false, NULL, NULL, NULL, 'quest_arcanum.json', 90)
