values ('fq_arc_092', 'Void Silence', 'hunt', 'S', 'THE_ARCANUM_SEEKERS', 'VOID_ECHO_CHASM', 'The Void is collapsing. (Location: Void Echo Chasm, Scholar Elara) The Arcanum must collect the final void data before it disappears forever. Every echo is precious.', '{"npc_id": "npc_arcanum_scholar", "name": "Scholar Elara", "location": "VOID_ECHO_CHASM"}'::jsonb, '{"min_level": 91, "reputation_required": 5400, "required_quests": ["fq_arc_091"]}'::jsonb, '[{"type": "kill", "target": "AETHEL_ABYSSAL_REAVER", "count": 10, "description": "Exterminate the final Abyssal Reavers. [Aethel Abyssal Reaver]"}, {"type": "collect", "target": "void_channeler_core", "count": 1, "description": "Collect void channeler core (x1). [Item: Void Channeler Core]"}]'::jsonb, '{"exp": 11000, "currency": 5500, "crd": 2750, "rep": 3500, "items": [{"item_id": "void_core", "quantity": 5}], "reputation": 50}'::jsonb, false, false, 'fq_arc_093', false, NULL, NULL, NULL, 'quest_arcanum.json', 91)
