values ('fq_arc_093', 'Tyrant''s Last Archive', 'boss', 'S', 'THE_ARCANUM_SEEKERS', 'SHATTERED_HEART', 'Crystal Tyrants in the Shattered Heart have absorbed the last remaining Precursor archives. Extract the knowledge from their crystalline bodies. Quest giver: Scholar Elara at Observatory Spire Research Wing.', '{"npc_id": "npc_arcanum_scholar", "name": "Scholar Elara", "location": "SHATTERED_HEART"}'::jsonb, '{"min_level": 92, "reputation_required": 5460, "required_quests": ["fq_arc_092"]}'::jsonb, '[{"type": "kill", "target": "CRYSTAL_TYRANT", "count": 3, "description": "Defeat the last Crystal Tyrants."}, {"type": "collect", "target": "core_fragment", "count": 1, "description": "Collect core fragment (x1). [Item: Core Fragment]"}]'::jsonb, '{"exp": 12000, "currency": 6000, "crd": 3000, "rep": 4000, "items": [{"item_id": "cognitive_relay_node", "quantity": 3}], "reputation": 50}'::jsonb, false, false, 'fq_arc_094', false, NULL, NULL, NULL, 'quest_arcanum.json', 92)
