values ('fq_arc_094', 'Forge Completion', 'hunt', 'S', 'THE_ARCANUM_SEEKERS', 'PRIMA_MATERIA_FORGE', 'The Forge will be the Arcanum''s eternal workshop. (Location: Prima Materia Forge, Scholar Elara) Purify the last remaining contamination and seal the facility.', '{"npc_id": "npc_arcanum_scholar", "name": "Scholar Elara", "location": "PRIMA_MATERIA_FORGE"}'::jsonb, '{"min_level": 93, "reputation_required": 5520, "required_quests": ["fq_arc_093"]}'::jsonb, '[{"type": "kill", "target": "AETHEL_VOID_CHANNELER", "count": 8, "description": "Silence the last Void Channelers. [Aethel Void Channeler]"}, {"type": "kill", "target": "TITAN_FORGE_AUTOMATON", "count": 3, "description": "Disable rogue Forge Automatons. [Titan Forge Automaton]"}]'::jsonb, '{"exp": 11000, "currency": 5500, "crd": 2750, "rep": 3500, "items": [{"item_id": "raw_aethel_core", "quantity": 5}], "reputation": 50}'::jsonb, false, false, 'fq_arc_095', false, NULL, NULL, NULL, 'quest_arcanum.json', 93)
