values ('fq_arc_095', 'Expanse Dominion', 'hunt', 'S', 'THE_ARCANUM_SEEKERS', 'CRADLE_EXPANSE', 'The Cradle Expanse is now Arcanum research territory. Enforce our intellectual sovereignty with overwhelming arcane power. Quest giver: Scholar Elara at Observatory Spire Research Wing.', '{"npc_id": "npc_arcanum_scholar", "name": "Scholar Elara", "location": "CRADLE_EXPANSE"}'::jsonb, '{"min_level": 94, "reputation_required": 5580, "required_quests": ["fq_arc_094"]}'::jsonb, '[{"type": "kill", "target": "AETHEL_RIFT_STALKER", "count": 10, "description": "Clear all hostiles from the Expanse. [Aethel Rift Stalker]"}, {"type": "kill", "target": "GRAVITY_TITAN", "count": 1, "description": "Destroy any residual Titan manifestations. [Gravity Titan]"}]'::jsonb, '{"exp": 13000, "currency": 6500, "crd": 3250, "rep": 4200, "items": [{"item_id": "gravity_well_core", "quantity": 3}], "reputation": 50}'::jsonb, false, false, 'fq_arc_096', false, NULL, NULL, NULL, 'quest_arcanum.json', 94)
