values ('fq_arc_096', 'Eternal Vigil', 'hunt', 'S', 'THE_ARCANUM_SEEKERS', 'ORBITAL_SENTINEL_COMMAND', 'From orbit, the Arcanum watches over Xylos — the planet that is now our greatest library. (Location: Orbital Sentinel Command, Scholar Elara) Maintain eternal vigilance over our domain of knowledge.', '{"npc_id": "npc_arcanum_scholar", "name": "Scholar Elara", "location": "ORBITAL_SENTINEL_COMMAND"}'::jsonb, '{"min_level": 95, "reputation_required": 5640, "required_quests": ["fq_arc_095"]}'::jsonb, '[{"type": "kill", "target": "AETHEL_IRON_CARAPACE", "count": 10, "description": "Patrol and secure orbital sectors. [Aethel Iron Carapace]"}, {"type": "kill", "target": "AETHEL_CORRUPTED_BEHEMOTH", "count": 3, "description": "Eliminate any remaining Corrupted Behemoths. [Aethel Corrupted Behemoth]"}]'::jsonb, '{"exp": 12000, "currency": 6000, "crd": 3000, "rep": 3800, "items": [{"item_id": "con_elite_recovery_pack", "quantity": 10}], "reputation": 50}'::jsonb, false, false, 'fq_arc_097', false, NULL, NULL, NULL, 'quest_arcanum.json', 95)
