values ('fq_arc_097', 'The Final Formula', 'story', 'S', 'THE_ARCANUM_SEEKERS', 'PRIMA_MATERIA_FORGE', 'The collected knowledge from all sources forms the Final Formula — the unified theory of Xylos. (Location: Prima Materia Forge, Scholar Elara) Channel all accumulated Arcanum knowledge into its completion.', '{"npc_id": "npc_arcanum_scholar", "name": "Scholar Elara", "location": "PRIMA_MATERIA_FORGE"}'::jsonb, '{"min_level": 96, "reputation_required": 580, "required_quests": ["fq_arc_096"]}'::jsonb, '[{"type": "kill", "target": "GIGANTIC_JOTUNN", "count": 3, "description": "Defeat Jotunns resisting the Final Formula. [Gigantic Jotunn]"}, {"type": "kill", "target": "ABYSS_HARBINGER", "count": 1, "description": "Destroy the Harbinger''s final echo. [Abyss Harbinger]"}, {"type": "collect", "target": "monster_material", "count": 3, "description": "Collect monster material (x3). [Item: Monster Material]"}]'::jsonb, '{"exp": 15000, "currency": 7500, "crd": 3750, "rep": 5000, "items": [{"item_id": "resonanted_astral_phase_crystal", "quantity": 2}], "reputation": 50}'::jsonb, false, false, 'fq_arc_098', false, NULL, NULL, NULL, 'quest_arcanum.json', 96)
