values ('fq_arc_098', 'The Final Convergence', 'story', 'S', 'THE_ARCANUM_SEEKERS', 'PRIMA_MATERIA_FORGE', 'Only the ultimate test remains. (Location: Prima Materia Forge, Scholar Elara) Face the three Apex entities — Jotunn, Drake, and Harbinger — and from their essences forge the Key of Absolute Knowledge.', '{"npc_id": "npc_arcanum_scholar", "name": "Scholar Elara", "location": "PRIMA_MATERIA_FORGE"}'::jsonb, '{"min_level": 97, "reputation_required": 630, "required_quests": ["fq_arc_097"]}'::jsonb, '[{"type": "kill", "target": "GIGANTIC_JOTUNN", "count": 1, "description": "Defeat the Apex Jotunn. [Gigantic Jotunn]"}, {"type": "kill", "target": "ASHEN_DRAKE", "count": 1, "description": "Defeat the Apex Drake. [Ashen Drake]"}, {"type": "kill", "target": "ABYSS_HARBINGER", "count": 1, "description": "Defeat the Apex Harbinger. [Abyss Harbinger]"}, {"type": "collect", "target": "core_fragment", "count": 1, "description": "Collect core fragment (x1). [Item: Core Fragment]"}]'::jsonb, '{"exp": 20000, "currency": 10000, "crd": 5000, "rep": 7000, "items": [{"item_id": "drake_heart", "quantity": 3}, {"item_id": "titan_core", "quantity": 3}, {"item_id": "void_core", "quantity": 5}], "reputation": 50}'::jsonb, false, false, 'fq_arc_099', false, NULL, NULL, NULL, 'quest_arcanum.json', 97)
