values ('fq_arc_099', 'Sovereign of Secrets', 'story', 'S', 'THE_ARCANUM_SEEKERS', 'VOID_ECHO_CHASM', 'The deepest Void Echo Chasm holds the final secret — the truth of Xylos''s creation. Descend one final time and claim the ultimate knowledge. Quest giver: Scholar Elara at Observatory Spire Research Wing.', '{"npc_id": "npc_arcanum_scholar", "name": "Scholar Elara", "location": "VOID_ECHO_CHASM"}'::jsonb, '{"min_level": 98, "reputation_required": 680, "required_quests": ["fq_arc_098"]}'::jsonb, '[{"type": "travel", "target": "VOID_ECHO_CHASM", "count": 1, "description": "Descend to the deepest chasm level. (Travel to: Void Echo Chasm)"}, {"type": "kill", "target": "GRAVITY_TITAN", "count": 1, "description": "Defeat the eternal form of Gravity Titan."}, {"type": "kill", "target": "ABYSS_HARBINGER", "count": 1, "description": "Destroy the eternal form of Abyss Harbinger."}, {"type": "collect", "target": "abyss_fragment", "count": 1, "description": "Collect abyss fragment (x1). [Item: Abyss Fragment]"}]'::jsonb, '{"exp": 25000, "currency": 12000, "crd": 6000, "rep": 8000, "items": [{"item_id": "resonanted_astral_phase_crystal", "quantity": 3}], "reputation": 50}'::jsonb, false, false, 'fq_arc_100', false, NULL, NULL, NULL, 'quest_arcanum.json', 98)
