values ('fq_arc_100', 'Eternity of Knowledge', 'story', 'SS', 'THE_ARCANUM_SEEKERS', 'OBSERVATORY_SPIRE', 'You have done the impossible. You hold the Sovereign Seal. Return to the Observatory Spire where all of the Arcanum Seekers await. You are no longer a Seeker. You are the SOVEREIGN OF SECRETS. Knowledge is Power. Secrets are Sovereignty. Now and forever. Quest giver: Scholar Elara at Observatory Spire Research Wing.', '{"npc_id": "npc_arcanum_scholar", "name": "Scholar Elara", "location": "OBSERVATORY_SPIRE"}'::jsonb, '{"min_level": 99, "reputation_required": 730, "required_quests": ["fq_arc_099"]}'::jsonb, '[{"type": "travel", "target": "OBSERVATORY_SPIRE", "count": 1, "description": "Return to the Observatory Spire as the Sovereign of Secrets."}, {"type": "interact", "target": "npc_arcanum_scholar", "count": 1, "description": "Receive the highest honors from High Seeker Elara. (Scholar Elara at Observatory Spire Research Wing)"}]'::jsonb, '{"exp": 50000, "currency": 25000, "crd": 0, "rep": 10000, "items": [{"item_id": "resonanted_astral_phase_crystal", "quantity": 5}, {"item_id": "sovereign_seal", "quantity": 1}], "reputation": 5}'::jsonb, false, false, NULL, false, NULL, NULL, NULL, 'quest_arcanum.json', 99)
