values ('fq_conc_004', 'What Grows in the Dark', 'story', 'D', 'CONCORDIUM', 'AETHEL_GARDENS', 'The aethel conduits threading through the Gardens were carved by the Concordium''s founders — some say they can still hear those engineers'' voices in the hum. (Location: Aethel Gardens, Officer Valen) Feral Rootlings have grown through the conduit walls, drinking raw aethel energy and warping into something that was never in any pre-Severance bestiary. Cut them out before the conduit lines fail and Nexus Core goes dark.', '{"npc_id": "npc_concordium_officer", "name": "Commander Lirien Vale", "location": "AETHEL_GARDENS"}'::jsonb, '{"min_level": 3, "reputation_required": 15, "required_quests": ["fq_conc_003"]}'::jsonb, '[{"type": "kill", "target": "FERAL_ROOTLING", "count": 6, "description": "Defeat Feral Rootlings near the aethel conduits."}, {"type": "collect", "target": "living_root", "count": 4, "description": "Collect living root (x4). [Item: Living Root]"}]'::jsonb, '{"exp": 80, "currency": 50, "crd": 0, "rep": 50, "items": [{"item_id": "con_nutrient_ration", "quantity": 2}], "reputation": 5}'::jsonb, false, false, 'fq_conc_005', false, NULL, NULL, NULL, 'quest_concordium.json', 3)
