insert into public.quests (id, title, type, rank, faction, region, description, quest_giver, requirements, objectives, rewards, repeatable, daily, quest_chain_next, popup, popup_trigger, popup_level, popup_prerequisite, source_file, sort_order)
values ('fq_conc_005', 'The Shape of a Soldier', 'tutorial', 'D', 'CONCORDIUM', 'NEXUS_CORE', 'Commander Vale''s field report reached Nexus Core faster than you expected. Instructor Kael — the Concordium''s master trainer, a veteran who fought in the earliest post-Schism skirmishes — has summoned you personally. Before the Concordium trusts you with the Cradle''s defense, you must choose your path. The Aethel Cradle wasn''t rebuilt by generalists.', '{"npc_id": "npc_concordium_class_trainer", "name": "Instructor Kael", "location": "NEXUS_CORE"}'::jsonb, '{"min_level": 4, "reputation_required": 20, "required_quests": ["fq_conc_004"], "required_items": ["recomendation_letters"]}'::jsonb, '[{"type": "interact", "target": "npc_concordium_class_trainer", "count": 1, "description": "Speak with Instructor Kael at Nexus Core. (Instructor Kael at Nexus Core Training Academy)"}, {"type": "interact", "target": "class_change_screen", "count": 1, "description": "Open the class selection screen and review available classes."}, {"type": "kill", "target": "FOREST_SLIME", "count": 3, "description": "Defeat Forest Slimes to demonstrate your training."}]'::jsonb, '{"exp": 400, "currency": 200, "crd": 0, "rep": 150, "items": [{"item_id": "wpn_iron_sword", "quantity": 1}, {"item_id": "armor_guard_chainmail", "quantity": 1}, {"item_id": "rare_emblem", "quantity": 1}, {"item_id": "echo_memory_core_low", "quantity": 1}], "reputation": 5}'::jsonb, false, false, 'fq_conc_006', true, 'on_quest_complete', 4, 'fq_conc_004', 'quest_concordium.json', 4)
