insert into public.quests (id, title, type, rank, faction, region, description, quest_giver, requirements, objectives, rewards, repeatable, daily, quest_chain_next, popup, popup_trigger, popup_level, popup_prerequisite, source_file, sort_order)
values ('fq_conc_006', 'What the Schism Left Behind', 'story', 'D', 'CONCORDIUM', 'BROKEN_CIVIL_QUARTER', 'The Broken Civil Quarter was once the beating heart of unified Nexus — before the Great Schism tore the Concordium into three factions and left these streets to rot. Concordium engineers have located a viable breach point to reclaim the district, but Tunnel Crawlers have nested in the main access corridor. Commander Vale''s orders are direct: clear it, stake the Concordium flag, and remind Xylos that unity is still possible. Quest giver: Officer Valen at Nexus Core Command Post.', '{"npc_id": "npc_concordium_officer", "name": "Commander Lirien Vale", "location": "BROKEN_CIVIL_QUARTER"}'::jsonb, '{"min_level": 5, "reputation_required": 20, "required_quests": ["fq_conc_005"]}'::jsonb, '[{"type": "kill", "target": "TUNNEL_CRAWLER", "count": 6, "description": "Defeat Tunnel Crawlers at the main breach."}, {"type": "collect", "target": "crawler_chitin", "count": 1, "description": "Collect crawler chitin (x1). [Item: Crawler Chitin]"}]'::jsonb, '{"exp": 100, "currency": 60, "crd": 0, "rep": 60, "items": [{"item_id": "mat_iron_ore", "quantity": 2}], "reputation": 5}'::jsonb, false, false, 'fq_conc_007', false, NULL, NULL, NULL, 'quest_concordium.json', 5)
