insert into public.quests (id, title, type, rank, faction, region, description, quest_giver, requirements, objectives, rewards, repeatable, daily, quest_chain_next, popup, popup_trigger, popup_level, popup_prerequisite, source_file, sort_order)
values ('fq_conc_007', 'Scavengers of the Schism', 'story', 'D', 'CONCORDIUM', 'BROKEN_CIVIL_QUARTER', 'The Broken Civil Quarter caches contain medical supplies, engineering manuals, and communication arrays — resources the original Concordium buried here against the day the Schism might be reversed. Scavengers have been looting them for years, selling them to the highest bidder. Commander Vale''s voice has an edge when she says it: some of those manuals were written by her mother. Quest giver: Officer Valen at Nexus Core Command Post.', '{"npc_id": "npc_concordium_officer", "name": "Commander Lirien Vale", "location": "BROKEN_CIVIL_QUARTER"}'::jsonb, '{"min_level": 6, "reputation_required": 25, "required_quests": ["fq_conc_006"]}'::jsonb, '[{"type": "kill", "target": "BROKEN_SCAVENGER", "count": 5, "description": "Eliminate scavengers in the ruined sector. [Broken Quarter Scavenger]"}, {"type": "collect", "target": "rusted_scrap", "count": 2, "description": "Collect rusted scrap (x2). [Item: Rusted Scrap]"}]'::jsonb, '{"exp": 120, "currency": 70, "crd": 0, "rep": 70, "items": [{"item_id": "scrap_metal", "quantity": 3}], "reputation": 5}'::jsonb, false, false, 'fq_conc_008', false, NULL, NULL, NULL, 'quest_concordium.json', 6)
