insert into public.quests (id, title, type, rank, faction, region, description, quest_giver, requirements, objectives, rewards, repeatable, daily, quest_chain_next, popup, popup_trigger, popup_level, popup_prerequisite, source_file, sort_order)
values ('fq_conc_008', 'The Alpha and the Archive', 'story', 'D', 'CONCORDIUM', 'BROKEN_CIVIL_QUARTER', 'A Civil Rat Alpha has claimed an old Concordium archive building, breeding a colony large enough to collapse the reclaimed sector''s food supply. (Location: Broken Civil Quarter, Guard Captain) The irony is not lost on Commander Vale — the Concordium survived the Severance, the Schism, and three rival factions, and now a rat threatens the advance. She wants that Alpha dead, and she wants a record kept of its nesting site. Everything is data.', '{"npc_id": "npc_patrol_guard", "name": "Commander Lirien Vale", "location": "BROKEN_CIVIL_QUARTER"}'::jsonb, '{"min_level": 7, "reputation_required": 30, "required_quests": ["fq_conc_007"]}'::jsonb, '[{"type": "kill", "target": "CIVIL_RAT_ALPHA", "count": 1, "description": "Hunt and defeat the Civil Rat Alpha."}, {"type": "kill", "target": "CIVIL_SCAVENGER", "count": 3, "description": "Clear out nearby Civil Scavengers. [Civil Quarter Scavenger]"}]'::jsonb, '{"exp": 180, "currency": 100, "crd": 0, "rep": 100, "items": [{"item_id": "rust_chitin", "quantity": 2}, {"item_id": "con_small_hp_cell", "quantity": 3}], "reputation": 5}'::jsonb, false, false, 'fq_conc_009', false, NULL, NULL, NULL, 'quest_concordium.json', 7)
