insert into public.quests (id, title, type, rank, faction, region, description, quest_giver, requirements, objectives, rewards, repeatable, daily, quest_chain_next, popup, popup_trigger, popup_level, popup_prerequisite, source_file, sort_order)
values ('fq_conc_009', 'The Last Sentinel', 'story', 'D', 'CONCORDIUM', 'BROKEN_CIVIL_QUARTER', 'A Rusted Warden — automated guardian tech from before the Schism — still patrols the ruins as if it has orders. (Location: Broken Civil Quarter, Officer Valen) It doesn''t recognize the Concordium''s current insignia. It doesn''t recognize anything except the threat-assessment protocols written into it a century ago. Vale wonders, quietly, whether the original Concordium ever planned for the machines to outlast the people who built them.', '{"npc_id": "npc_concordium_officer", "name": "Commander Lirien Vale", "location": "BROKEN_CIVIL_QUARTER"}'::jsonb, '{"min_level": 8, "reputation_required": 35, "required_quests": ["fq_conc_008"]}'::jsonb, '[{"type": "kill", "target": "RUSTED_WARDEN", "count": 2, "description": "Defeat Rusted Wardens guarding the deep ruins."}, {"type": "kill", "target": "FERAL_SCAVENGER", "count": 4, "description": "Clear Feral Scavengers from the perimeter."}]'::jsonb, '{"exp": 220, "currency": 120, "crd": 0, "rep": 120, "items": [{"item_id": "scrap_circuit", "quantity": 2}, {"item_id": "rusted_plate", "quantity": 1}], "reputation": 5}'::jsonb, false, false, 'fq_conc_010', false, NULL, NULL, NULL, 'quest_concordium.json', 8)
on conflict (id) do update set title = excluded.title, type = excluded.type, rank = excluded.rank, faction = excluded.faction, region = excluded.region, description = excluded.description, quest_giver = excluded.quest_giver, requirements = excluded.requirements, objectives = excluded.objectives, rewards = excluded.rewards, repeatable = excluded.repeatable, daily = excluded.daily, quest_chain_next = excluded.quest_chain_next, popup = excluded.popup, popup_trigger = excluded.popup_trigger, popup_level = excluded.popup_level, popup_prerequisite = excluded.popup_prerequisite, source_file = excluded.source_file, sort_order = excluded.sort_order;
insert into public.quests (id, title, type, rank, faction, region, description, quest_giver, requirements, objectives, rewards, repeatable, daily, quest_chain_next, popup, popup_trigger, popup_level, popup_prerequisite, source_file, sort_order)
values ('fq_conc_010', 'King of a Broken City', 'story', 'D', 'CONCORDIUM', 'BROKEN_CIVIL_QUARTER', 'The sewers beneath the Civil Quarter were engineered by the Concordium''s founders as emergency water routing — now they''re the throne room of a Slime King, a massive Severance-spawn that has been growing in the dark for years. (Location: Broken Civil Quarter, Officer Valen) It is the embodiment of everything the Concordium is fighting against: the Severance''s corruption, enthroned in the ruins of what Xylos once was. Commander Vale''s message is simple: end its reign.', '{"npc_id": "npc_concordium_officer", "name": "Commander Lirien Vale", "location": "BROKEN_CIVIL_QUARTER"}'::jsonb, '{"min_level": 9, "reputation_required": 40, "required_quests": ["fq_conc_009"]}'::jsonb, '[{"type": "kill", "target": "SLIME_KING", "count": 1, "description": "Defeat the Slime King in the underground cistern."}, {"type": "kill", "target": "CIVIL_MUTANT_HOUND", "count": 2, "description": "Eliminate mutant hounds protecting the King. [Civil Mutant Hound]"}]'::jsonb, '{"exp": 350, "currency": 200, "crd": 0, "rep": 200, "items": [{"item_id": "slime_core", "quantity": 1}, {"item_id": "slime_gel", "quantity": 5}], "reputation": 5}'::jsonb, false, false, 'fq_conc_011', false, NULL, NULL, NULL, 'quest_concordium.json', 9)
