values ('fq_conc_011', 'The Heart''s Outer Wall', 'story', 'C', 'CONCORDIUM', 'CRADLE_OUTER_RING', 'You''ve earned the right to see it — the Aethel Cradle''s Outer Ring, the great machine the Concordium built around the planet''s most powerful energy source. (Location: Cradle Outer Ring, Officer Valen) It hums with a sound older than recorded history, and Commander Vale says the original engineers wept when they first activated it. Now the Outer Ring is contested ground, and every faction wants what it contains. Your mission: scout it and make sure the Concordium holds the advantage.', '{"npc_id": "npc_concordium_officer", "name": "Commander Lirien Vale", "location": "CRADLE_OUTER_RING"}'::jsonb, '{"min_level": 10, "reputation_required": 45, "required_quests": ["fq_conc_010"]}'::jsonb, '[{"type": "travel", "target": "CRADLE_OUTER_RING", "count": 1, "description": "Travel to the Cradle Outer Ring."}, {"type": "collect", "target": "void_fragment", "count": 3, "description": "Collect void fragment (x3). [Item: Void Fragment]"}]'::jsonb, '{"exp": 280, "currency": 150, "crd": 0, "rep": 150, "items": [{"item_id": "con_minor_stim_pack", "quantity": 2}], "reputation": 5}'::jsonb, false, false, 'fq_conc_012', false, NULL, NULL, NULL, 'quest_concordium.json', 10)
