values ('fq_conc_015', 'Static Over the Cradle', 'story', 'C', 'CONCORDIUM', 'CRADLE_OUTER_RING', 'Resonance Bats — creatures that evolved using the Cradle''s own harmonic emissions as echolocation — have been jamming the communication arrays that coordinate Concordium''s Outer Ring defenses. (Location: Cradle Outer Ring, Officer Valen) The last three hours have been radio silence from Sector Seven. Commander Vale doesn''t say the word "scared" but she checks the comms every thirty seconds. Clear the bats and bring back contact.', '{"npc_id": "npc_concordium_officer", "name": "Commander Lirien Vale", "location": "CRADLE_OUTER_RING"}'::jsonb, '{"min_level": 14, "reputation_required": 65, "required_quests": ["fq_conc_014"]}'::jsonb, '[{"type": "kill", "target": "RESONANCE_BAT", "count": 8, "description": "Defeat Resonance Bats near the comm array."}, {"type": "kill", "target": "RESONANCE_GOLEM", "count": 2, "description": "Destroy Resonance Golems guarding the nest."}]'::jsonb, '{"exp": 500, "currency": 280, "crd": 0, "rep": 300, "items": [{"item_id": "psionic_resonator", "quantity": 1}], "reputation": 5}'::jsonb, false, false, 'fq_conc_016', false, NULL, NULL, NULL, 'quest_concordium.json', 14)
