values ('fq_conc_018', 'The Golems Remember', 'story', 'C', 'CONCORDIUM', 'CRADLE_OUTER_RING', 'Resonance Golems are not random creatures — Concordium historians believe they are the Aethel Cradle''s original defense constructs, built by the same Aethelgardian engineers who first activated the Siphon. (Location: Cradle Outer Ring, Officer Valen) They have been nesting in the deep Outer Ring and their harmonic pulses are rewriting the Concordium''s own signal protocols with something older and stranger. Commander Vale wants them destroyed, but she orders you to document their emissions first. The Concordium does not discard knowledge.', '{"npc_id": "npc_concordium_officer", "name": "Commander Lirien Vale", "location": "CRADLE_OUTER_RING"}'::jsonb, '{"min_level": 17, "reputation_required": 80, "required_quests": ["fq_conc_017"]}'::jsonb, '[{"type": "kill", "target": "RESONANCE_GOLEM", "count": 3, "description": "Defeat Resonance Golems in the deep chambers."}, {"type": "kill", "target": "RESONANCE_BAT", "count": 6, "description": "Clear out the surrounding bat swarm. [Resonance Bat]"}]'::jsonb, '{"exp": 550, "currency": 300, "crd": 0, "rep": 320, "items": [{"item_id": "cognitive_relay_node", "quantity": 1}], "reputation": 5}'::jsonb, false, false, 'fq_conc_019', false, NULL, NULL, NULL, 'quest_concordium.json', 17)
