insert into public.quests (id, title, type, rank, faction, region, description, quest_giver, requirements, objectives, rewards, repeatable, daily, quest_chain_next, popup, popup_trigger, popup_level, popup_prerequisite, source_file, sort_order)
values ('fq_conc_019', 'Voice of the Old Machine', 'story', 'C', 'CONCORDIUM', 'CRADLE_OUTER_RING', 'The Resonance Echo is not just a creature — it is a concentrated echo of the Cradle''s original harmonic signature, coalesced into something almost conscious. (Location: Cradle Outer Ring, Officer Valen) The Arcanum Seekers would call it a miracle. The Children of the Shard would call it a god-fragment. Commander Vale calls it a threat to Concordium communication infrastructure, and she is right on all fronts. Defeat it. Whatever it is, it cannot be allowed to rewrite the Cradle on its own terms.', '{"npc_id": "npc_concordium_officer", "name": "Commander Lirien Vale", "location": "CRADLE_OUTER_RING"}'::jsonb, '{"min_level": 18, "reputation_required": 85, "required_quests": ["fq_conc_018"]}'::jsonb, '[{"type": "kill", "target": "RESONANCE_ECHO", "count": 1, "description": "Defeat the Resonance Echo at the resonance chamber."}, {"type": "kill", "target": "CRADLE_FRAGMENT_BEAST", "count": 4, "description": "Clear remaining Fragment Beasts from the area. [Cradle Fragment Beast]"}]'::jsonb, '{"exp": 800, "currency": 450, "crd": 0, "rep": 450, "items": [{"item_id": "entropy_core", "quantity": 1}, {"item_id": "con_medium_hp_cell", "quantity": 3}], "reputation": 5}'::jsonb, false, false, 'fq_conc_020', false, NULL, NULL, NULL, 'quest_concordium.json', 18)
