insert into public.quests (id, title, type, rank, faction, region, description, quest_giver, requirements, objectives, rewards, repeatable, daily, quest_chain_next, popup, popup_trigger, popup_level, popup_prerequisite, source_file, sort_order)
values ('fq_conc_020', 'The Outer Ring is Ours', 'story', 'C', 'CONCORDIUM', 'CRADLE_OUTER_RING', 'The Outer Ring is not fully secured — it never will be, not while three factions and something older than any of them push against the Concordium''s borders. (Location: Cradle Outer Ring, Officer Valen) But the Concordium holds more of it today than it did a season ago, and that is because of what you''ve done here. Commander Vale''s final sweep order is also a test: the Concordium is preparing to evaluate you for Advanced assignment. The Cradle''s inner platforms await.', '{"npc_id": "npc_concordium_officer", "name": "Commander Lirien Vale", "location": "CRADLE_OUTER_RING"}'::jsonb, '{"min_level": 19, "reputation_required": 90, "required_quests": ["fq_conc_019"]}'::jsonb, '[{"type": "kill", "target": "CRADLE_ANOMALY_BEASTLING", "count": 5, "description": "Final sweep: defeat remaining Beastlings. [Cradle Anomaly Beastling]"}, {"type": "kill", "target": "RESONANCE_BAT", "count": 5, "description": "Final sweep: eliminate remaining Resonance Bats."}, {"type": "collect", "target": "void_fragment", "count": 1, "description": "Collect void fragment (x1). [Item: Void Fragment]"}]'::jsonb, '{"exp": 900, "currency": 500, "crd": 0, "rep": 500, "items": [{"item_id": "con_medium_hp_cell", "quantity": 5}, {"item_id": "con_medium_mp_cell", "quantity": 3}], "reputation": 5}'::jsonb, false, false, 'fq_conc_021', false, NULL, NULL, NULL, 'quest_concordium.json', 19)
