values ('fq_conc_021', 'Deep Incursion', 'exploration', 'B', 'CONCORDIUM', 'INNER_CRADLE_EXCLUSION', 'Push deeper into the Inner Cradle Exclusion. Intel suggests powerful ancient technology lies dormant within. Quest giver: Officer Valen at Nexus Core Command Post.', '{"npc_id": "npc_concordium_officer", "name": "", "location": "INNER_CRADLE_EXCLUSION"}'::jsonb, '{"min_level": 20, "reputation_required": 1140, "required_quests": ["fq_conc_020"]}'::jsonb, '[{"type": "travel", "target": "INNER_CRADLE_EXCLUSION", "count": 1, "description": "Enter the Inner Cradle Exclusion zone."}, {"type": "collect", "target": "monster_material", "count": 2, "description": "Collect monster material (x2). [Item: Monster Material]"}]'::jsonb, '{"exp": 600, "currency": 350, "crd": 105, "rep": 350, "items": [{"item_id": "con_nutrient_ration", "quantity": 3}], "reputation": 10}'::jsonb, false, false, 'fq_conc_022', false, NULL, NULL, NULL, 'quest_concordium.json', 20)
