values ('fq_conc_022', 'Mutant Strain', 'hunt', 'B', 'CONCORDIUM', 'INNER_CRADLE_EXCLUSION', 'Inner Cradle Mutants exposed to raw aethel show extreme aggression. (Location: Inner Cradle Exclusion, Officer Valen) Eliminate the threat and take tissue samples.', '{"npc_id": "npc_concordium_officer", "name": "", "location": "INNER_CRADLE_EXCLUSION"}'::jsonb, '{"min_level": 21, "reputation_required": 1200, "required_quests": ["fq_conc_021"]}'::jsonb, '[{"type": "kill", "target": "INNER_CRADLE_MUTANT", "count": 6, "description": "Defeat Inner Cradle Mutants."}, {"type": "collect", "target": "mutant_claw", "count": 3, "description": "Collect mutant claw (x3). [Item: Mutant Claw]"}]'::jsonb, '{"exp": 650, "currency": 380, "crd": 114, "rep": 380, "items": [{"item_id": "mutagen_catalyst", "quantity": 1}], "reputation": 10}'::jsonb, false, false, 'fq_conc_023', false, NULL, NULL, NULL, 'quest_concordium.json', 21)
