values ('fq_conc_023', 'Behemoth Rising', 'boss', 'B', 'CONCORDIUM', 'INNER_CRADLE_EXCLUSION', 'An Inner Cradle Behemoth has been spotted in the deep exclusion. (Location: Inner Cradle Exclusion, Officer Valen) This threat must be neutralized immediately.', '{"npc_id": "npc_concordium_officer", "name": "", "location": "INNER_CRADLE_EXCLUSION"}'::jsonb, '{"min_level": 22, "reputation_required": 1260, "required_quests": ["fq_conc_022"]}'::jsonb, '[{"type": "kill", "target": "INNER_CRADLE_BEHEMOTH", "count": 1, "description": "Defeat the Inner Cradle Behemoth."}, {"type": "kill", "target": "INNER_CRADLE_MUTANT", "count": 4, "description": "Clear out mutant escorts protecting the Behemoth. [Inner Cradle Mutant]"}]'::jsonb, '{"exp": 750, "currency": 420, "crd": 126, "rep": 450, "items": [{"item_id": "titan_core", "quantity": 1}], "reputation": 10}'::jsonb, false, false, 'fq_conc_024', false, NULL, NULL, NULL, 'quest_concordium.json', 22)
