values ('fq_conc_024', 'Sentinel Protocol', 'hunt', 'B', 'CONCORDIUM', 'INNER_CRADLE_EXCLUSION', 'Cradle Sentinels guard the ancient Cradle gates. (Location: Inner Cradle Exclusion, Officer Valen) They must be disabled for Concordium to advance.', '{"npc_id": "npc_concordium_officer", "name": "", "location": "INNER_CRADLE_EXCLUSION"}'::jsonb, '{"min_level": 23, "reputation_required": 1320, "required_quests": ["fq_conc_023"]}'::jsonb, '[{"type": "kill", "target": "CRADLE_SENTINEL", "count": 4, "description": "Disable Cradle Sentinels at the ancient gate."}, {"type": "collect", "target": "aethel_core_shard", "count": 2, "description": "Collect aethel core shard (x2). [Item: Aethel Core Shard]"}]'::jsonb, '{"exp": 700, "currency": 400, "crd": 120, "rep": 400, "items": [{"item_id": "damaged_servo_motor", "quantity": 2}], "reputation": 10}'::jsonb, false, false, 'fq_conc_025', false, NULL, NULL, NULL, 'quest_concordium.json', 23)
