values ('fq_conc_025', 'Void Stalker', 'boss', 'B', 'CONCORDIUM', 'INNER_CRADLE_EXCLUSION', 'A Cradle Void Stalker has been hunting Concordium operatives in the Exclusion. (Location: Inner Cradle Exclusion, Officer Valen) Track it and eliminate the threat.', '{"npc_id": "npc_concordium_officer", "name": "", "location": "INNER_CRADLE_EXCLUSION"}'::jsonb, '{"min_level": 24, "reputation_required": 1380, "required_quests": ["fq_conc_024"]}'::jsonb, '[{"type": "kill", "target": "CRADLE_VOID_STALKER", "count": 2, "description": "Hunt and defeat Cradle Void Stalkers."}, {"type": "collect", "target": "core_fragment", "count": 1, "description": "Collect core fragment (x1). [Item: Core Fragment]"}]'::jsonb, '{"exp": 780, "currency": 440, "crd": 132, "rep": 470, "items": [{"item_id": "void_core", "quantity": 1}], "reputation": 10}'::jsonb, false, false, 'fq_conc_026', false, NULL, NULL, NULL, 'quest_concordium.json', 24)
