values ('fq_conc_026', 'Titanling Threat', 'boss', 'B', 'CONCORDIUM', 'INNER_CRADLE_EXCLUSION', 'Cradle Void Titanlings are immature but dangerous. (Location: Inner Cradle Exclusion, Officer Valen) Stop them before they mature into true Titans.', '{"npc_id": "npc_concordium_officer", "name": "", "location": "INNER_CRADLE_EXCLUSION"}'::jsonb, '{"min_level": 25, "reputation_required": 1440, "required_quests": ["fq_conc_025"]}'::jsonb, '[{"type": "kill", "target": "CRADLE_VOID_TITANLING", "count": 3, "description": "Defeat Cradle Void Titanlings."}, {"type": "kill", "target": "CRADLE_SENTINEL", "count": 2, "description": "Clear Sentinel guards from the Titanling nest. [Cradle Sentinel]"}]'::jsonb, '{"exp": 850, "currency": 480, "crd": 144, "rep": 500, "items": [{"item_id": "void_crystal_shard", "quantity": 2}], "reputation": 10}'::jsonb, false, false, 'fq_conc_027', false, NULL, NULL, NULL, 'quest_concordium.json', 25)
