values ('fq_conc_027', 'Into the Expanse', 'exploration', 'B', 'CONCORDIUM', 'CRADLE_EXPANSE', 'The Cradle Expanse is a contested zone between factions. Concordium needs forward positions. Move in and establish control. Quest giver: Officer Valen at Nexus Core Command Post.', '{"npc_id": "npc_concordium_officer", "name": "", "location": "CRADLE_EXPANSE"}'::jsonb, '{"min_level": 26, "reputation_required": 1500, "required_quests": ["fq_conc_026"]}'::jsonb, '[{"type": "travel", "target": "CRADLE_EXPANSE", "count": 1, "description": "Enter the Cradle Expanse conflict zone."}, {"type": "collect", "target": "core_fragment", "count": 2, "description": "Collect core fragment (x2). [Item: Core Fragment]"}]'::jsonb, '{"exp": 700, "currency": 400, "crd": 120, "rep": 400, "items": [{"item_id": "con_nutrient_ration", "quantity": 3}], "reputation": 10}'::jsonb, false, false, 'fq_conc_028', false, NULL, NULL, NULL, 'quest_concordium.json', 26)
