values ('fq_conc_028', 'Expanse Patrol', 'hunt', 'B', 'CONCORDIUM', 'CRADLE_EXPANSE', 'Aethel Rift Stalkers prowl the Expanse threatening all faction operations. (Location: Cradle Expanse, Officer Valen) Clear them out systematically.', '{"npc_id": "npc_concordium_officer", "name": "", "location": "CRADLE_EXPANSE"}'::jsonb, '{"min_level": 27, "reputation_required": 1560, "required_quests": ["fq_conc_027"]}'::jsonb, '[{"type": "kill", "target": "AETHEL_RIFT_STALKER", "count": 6, "description": "Defeat Aethel Rift Stalkers in the Expanse."}, {"type": "collect", "target": "rift_claw_fragment", "count": 2, "description": "Collect rift claw fragment (x2). [Item: Rift Claw Fragment]"}]'::jsonb, '{"exp": 750, "currency": 430, "crd": 129, "rep": 430, "items": [{"item_id": "dark_energy_fragment", "quantity": 2}], "reputation": 10}'::jsonb, false, false, 'fq_conc_029', false, NULL, NULL, NULL, 'quest_concordium.json', 27)
