values ('fq_conc_029', 'Behemoth Purge', 'boss', 'B', 'CONCORDIUM', 'CRADLE_EXPANSE', 'Aethel Behemoths roam the Expanse. (Location: Cradle Expanse, Officer Valen) These elite creatures cannot be allowed to threaten Concordium supply lines.', '{"npc_id": "npc_concordium_officer", "name": "", "location": "CRADLE_EXPANSE"}'::jsonb, '{"min_level": 28, "reputation_required": 1620, "required_quests": ["fq_conc_028"]}'::jsonb, '[{"type": "kill", "target": "AETHEL_BEHEMOTH", "count": 2, "description": "Defeat Aethel Behemoths in the Expanse."}, {"type": "kill", "target": "AETHEL_RIFT_STALKER", "count": 4, "description": "Clear Rift Stalkers from the hunting ground. [Aethel Rift Stalker]"}]'::jsonb, '{"exp": 900, "currency": 520, "crd": 156, "rep": 520, "items": [{"item_id": "aethel_core_shard", "quantity": 2}], "reputation": 10}'::jsonb, false, false, 'fq_conc_030', false, NULL, NULL, NULL, 'quest_concordium.json', 28)
