values ('fq_conc_030', 'The Ascension', 'story', 'B', 'CONCORDIUM', 'NEXUS_CORE', 'You have reached the Advanced threshold. Return to Instructor Kael at Nexus Core for your Ascension trial.', '{"npc_id": "npc_concordium_class_trainer", "name": "Instructor Kael", "location": "NEXUS_CORE"}'::jsonb, '{"min_level": 29, "reputation_required": 95, "required_quests": ["fq_conc_029"]}'::jsonb, '[{"type": "interact", "target": "npc_concordium_class_trainer", "count": 1, "description": "Report to Instructor Kael for Ascension evaluation. (Instructor Kael at Nexus Core Training Academy)"}, {"type": "kill", "target": "RESONANCE_ECHO", "count": 1, "description": "Defeat the Resonance Echo to prove your growth."}, {"type": "kill", "target": "AETHEL_BEHEMOTH", "count": 1, "description": "Hunt an Aethel Behemoth as your final trial."}]'::jsonb, '{"exp": 2500, "currency": 1200, "crd": 360, "rep": 800, "items": [{"item_id": "con_elite_recovery_pack", "quantity": 2}, {"item_id": "astral_phase_crystal_pure", "quantity": 1}], "reputation": 10}'::jsonb, false, false, 'fq_conc_031', true, 'on_quest_complete', 29, 'fq_conc_029', 'quest_concordium.json', 29)
