values ('fq_conc_031', 'Orbital Sovereignty', 'exploration', 'A', 'CONCORDIUM', 'ORBITAL_SENTINEL_COMMAND', 'Concordium high command summons you to the Orbital Sentinel Command. The faction wars have escalated to a new phase. Quest giver: Officer Valen at Nexus Core Command Post.', '{"npc_id": "npc_concordium_officer", "name": "", "location": "ORBITAL_SENTINEL_COMMAND"}'::jsonb, '{"min_level": 30, "reputation_required": 1740, "required_quests": ["fq_conc_030"]}'::jsonb, '[{"type": "travel", "target": "ORBITAL_SENTINEL_COMMAND", "count": 1, "description": "Report to Orbital Sentinel Command."}, {"type": "collect", "target": "monster_material", "count": 1, "description": "Collect monster material (x1). [Item: Monster Material]"}]'::jsonb, '{"exp": 900, "currency": 500, "crd": 250, "rep": 500, "items": [{"item_id": "con_elite_recovery_pack", "quantity": 1}], "reputation": 25}'::jsonb, false, false, 'fq_conc_032', false, NULL, NULL, NULL, 'quest_concordium.json', 30)
