values ('fq_conc_033', 'Corrupted Behemoth', 'boss', 'A', 'CONCORDIUM', 'CRADLE_EXPANSE', 'An Aethel Corrupted Behemoth rampages near the orbital tether. (Location: Cradle Expanse, Officer Valen) End its destruction before the tether is severed.', '{"npc_id": "npc_concordium_officer", "name": "", "location": "CRADLE_EXPANSE"}'::jsonb, '{"min_level": 32, "reputation_required": 1860, "required_quests": ["fq_conc_032"]}'::jsonb, '[{"type": "kill", "target": "AETHEL_CORRUPTED_BEHEMOTH", "count": 2, "description": "Defeat Corrupted Behemoths near the orbital tether. [Aethel Corrupted Behemoth]"}, {"type": "kill", "target": "AETHEL_IRON_CARAPACE", "count": 3, "description": "Clear Carapace escorts protecting the Behemoth. [Aethel Iron Carapace]"}]'::jsonb, '{"exp": 1200, "currency": 650, "crd": 325, "rep": 650, "items": [{"item_id": "aethel_fragment", "quantity": 2}], "reputation": 25}'::jsonb, false, false, 'fq_conc_034', false, NULL, NULL, NULL, 'quest_concordium.json', 32)
