values ('fq_conc_036', 'Orbital Defense', 'hunt', 'A', 'CONCORDIUM', 'ORBITAL_SENTINEL_COMMAND', 'Rival factions are probing Concordium''s orbital defenses. (Location: Orbital Sentinel Command, Officer Valen) Repel all intruders in the command sector with extreme prejudice.', '{"npc_id": "npc_concordium_officer", "name": "", "location": "ORBITAL_SENTINEL_COMMAND"}'::jsonb, '{"min_level": 35, "reputation_required": 2040, "required_quests": ["fq_conc_035"]}'::jsonb, '[{"type": "kill", "target": "AETHEL_RIFT_STALKER", "count": 6, "description": "Repel intruder forces in the orbital sector. [Aethel Rift Stalker]"}, {"type": "kill", "target": "AETHEL_VOID_CHANNELER", "count": 3, "description": "Neutralize hostile Void Channelers attempting orbital breach. [Aethel Void Channeler]"}]'::jsonb, '{"exp": 1500, "currency": 800, "crd": 400, "rep": 800, "items": [{"item_id": "con_elite_recovery_pack", "quantity": 3}], "reputation": 25}'::jsonb, false, false, 'fq_conc_037', false, NULL, NULL, NULL, 'quest_concordium.json', 35)
