values ('fq_conc_037', 'Dragon''s Shadow', 'boss', 'A', 'CONCORDIUM', 'CRADLE_EXPANSE', 'Reports confirm: the legendary Ashen Drake hunts in the Expanse. (Location: Cradle Expanse, Officer Valen) It is the apex predator of this sector. Engage with extreme caution — survival is the primary objective.', '{"npc_id": "npc_concordium_officer", "name": "", "location": "CRADLE_EXPANSE"}'::jsonb, '{"min_level": 36, "reputation_required": 2100, "required_quests": ["fq_conc_036"]}'::jsonb, '[{"type": "kill", "target": "ASHEN_DRAKE", "count": 1, "description": "Confront and survive against the Ashen Drake."}, {"type": "collect", "target": "ancient_scale", "count": 1, "description": "Collect ancient scale (x1). [Item: Ancient Scale]"}]'::jsonb, '{"exp": 3000, "currency": 1500, "crd": 750, "rep": 1000, "items": [{"item_id": "drake_heart", "quantity": 1}, {"item_id": "con_elite_recovery_pack", "quantity": 3}], "reputation": 25}'::jsonb, false, false, 'fq_conc_038', false, NULL, NULL, NULL, 'quest_concordium.json', 36)
