values ('fq_conc_038', 'Sentinel Command Purge', 'hunt', 'A', 'CONCORDIUM', 'ORBITAL_SENTINEL_COMMAND', 'Enemy infiltrators use orbital debris as cover. (Location: Orbital Sentinel Command, Officer Valen) Sweep the entire command sector clean.', '{"npc_id": "npc_concordium_officer", "name": "", "location": "ORBITAL_SENTINEL_COMMAND"}'::jsonb, '{"min_level": 37, "reputation_required": 2160, "required_quests": ["fq_conc_037"]}'::jsonb, '[{"type": "kill", "target": "AETHEL_IRON_CARAPACE", "count": 5, "description": "Clean out Carapace infiltrators from orbital sector. [Aethel Iron Carapace]"}, {"type": "kill", "target": "AETHEL_CORRUPTED_BEHEMOTH", "count": 1, "description": "Eliminate the Corrupted Behemoth leading the infiltration. [Aethel Corrupted Behemoth]"}]'::jsonb, '{"exp": 1700, "currency": 900, "crd": 450, "rep": 900, "items": [{"item_id": "stabilizer_gyro_unit", "quantity": 1}], "reputation": 25}'::jsonb, false, false, 'fq_conc_039', false, NULL, NULL, NULL, 'quest_concordium.json', 37)
