values ('fq_conc_039', 'Abyssal Tide', 'boss', 'A', 'CONCORDIUM', 'CRADLE_EXPANSE', 'Multiple Abyssal Reavers converge on the Expanse in a coordinated assault. (Location: Cradle Expanse, Officer Valen) Break their formation before they reach Command.', '{"npc_id": "npc_concordium_officer", "name": "", "location": "CRADLE_EXPANSE"}'::jsonb, '{"min_level": 38, "reputation_required": 2220, "required_quests": ["fq_conc_038"]}'::jsonb, '[{"type": "kill", "target": "AETHEL_ABYSSAL_REAVER", "count": 5, "description": "Defeat the Abyssal Reaver assault force. [Aethel Abyssal Reaver]"}, {"type": "kill", "target": "AETHEL_VOID_CHANNELER", "count": 3, "description": "Silence the summoning Channelers fueling the assault. [Aethel Void Channeler]"}]'::jsonb, '{"exp": 2000, "currency": 1100, "crd": 550, "rep": 1100, "items": [{"item_id": "gravity_well_core", "quantity": 1}], "reputation": 25}'::jsonb, false, false, 'fq_conc_040', false, NULL, NULL, NULL, 'quest_concordium.json', 38)
