values ('fq_conc_040', 'The Master Ascension', 'story', 'A', 'CONCORDIUM', 'CRADLE_EXPANSE', 'The final trial for Master rank. (Location: Cradle Expanse, Officer Valen) Defeat the Ashen Drake and two elite entities to unlock the full potential of your power. Concordium expects nothing less than absolute victory.', '{"npc_id": "npc_concordium_officer", "name": "", "location": "CRADLE_EXPANSE"}'::jsonb, '{"min_level": 39, "reputation_required": 105, "required_quests": ["fq_conc_039"]}'::jsonb, '[{"type": "kill", "target": "ASHEN_DRAKE", "count": 1, "description": "Hunt and defeat the Ashen Drake in the Expanse."}, {"type": "kill", "target": "AETHEL_BEHEMOTH", "count": 1, "description": "Defeat an Aethel Behemoth as your strength trial."}, {"type": "kill", "target": "AETHEL_ABYSSAL_REAVER", "count": 1, "description": "Slay an Aethel Abyssal Reaver as your resolve trial."}]'::jsonb, '{"exp": 5000, "currency": 2500, "crd": 1250, "rep": 2000, "items": [{"item_id": "drake_heart", "quantity": 1}, {"item_id": "void_core", "quantity": 2}, {"item_id": "con_elite_recovery_pack", "quantity": 5}], "reputation": 25}'::jsonb, false, false, 'fq_conc_041', false, NULL, NULL, NULL, 'quest_concordium.json', 39)
