values ('fq_conc_041', 'Into the Chasm', 'exploration', 'A', 'CONCORDIUM', 'VOID_ECHO_CHASM', 'You descend into the Void Echo Chasm — a realm where reality frays at the edges. Concordium suspects ancient relics and a growing threat lie within. Quest giver: Officer Valen at Nexus Core Command Post.', '{"npc_id": "npc_concordium_officer", "name": "", "location": "VOID_ECHO_CHASM"}'::jsonb, '{"min_level": 40, "reputation_required": 2340, "required_quests": ["fq_conc_040"]}'::jsonb, '[{"type": "travel", "target": "VOID_ECHO_CHASM", "count": 1, "description": "Enter the Void Echo Chasm."}, {"type": "collect", "target": "core_fragment", "count": 2, "description": "Collect core fragment (x2). [Item: Core Fragment]"}]'::jsonb, '{"exp": 1800, "currency": 900, "crd": 450, "rep": 600, "items": [{"item_id": "void_fragment", "quantity": 3}], "reputation": 25}'::jsonb, false, false, 'fq_conc_042', false, NULL, NULL, NULL, 'quest_concordium.json', 40)
