values ('fq_conc_042', 'Void Reaver Hunt', 'hunt', 'A', 'CONCORDIUM', 'VOID_ECHO_CHASM', 'Void Reavers — twisted entities born from the void — infest the upper chasm. (Location: Void Echo Chasm, Officer Valen) Purge them with Concordium fury.', '{"npc_id": "npc_concordium_officer", "name": "", "location": "VOID_ECHO_CHASM"}'::jsonb, '{"min_level": 41, "reputation_required": 2400, "required_quests": ["fq_conc_041"]}'::jsonb, '[{"type": "kill", "target": "VOID_REAVER", "count": 5, "description": "Defeat Void Reavers in the upper chasm."}, {"type": "collect", "target": "void_fragment", "count": 2, "description": "Collect void fragment (x2). [Item: Void Fragment]"}]'::jsonb, '{"exp": 1900, "currency": 950, "crd": 475, "rep": 650, "items": [{"item_id": "void_core", "quantity": 1}], "reputation": 25}'::jsonb, false, false, 'fq_conc_043', false, NULL, NULL, NULL, 'quest_concordium.json', 41)
