values ('fq_conc_043', 'Harbinger Signs', 'story', 'A', 'CONCORDIUM', 'VOID_ECHO_CHASM', 'Strange energies pulse from the deepest chasm. (Location: Void Echo Chasm, Officer Valen) Investigate the source — these match ancient records of the Abyss Harbinger.', '{"npc_id": "npc_concordium_officer", "name": "", "location": "VOID_ECHO_CHASM"}'::jsonb, '{"min_level": 42, "reputation_required": 130, "required_quests": ["fq_conc_042"]}'::jsonb, '[{"type": "kill", "target": "AETHEL_VOID_CHANNELER", "count": 6, "description": "Defeat Void Channelers performing dark rituals. [Aethel Void Channeler]"}, {"type": "collect", "target": "void_channeler_core", "count": 3, "description": "Collect void channeler core (x3). [Item: Void Channeler Core]"}]'::jsonb, '{"exp": 2100, "currency": 1050, "crd": 525, "rep": 700, "items": [{"item_id": "event_horizon_fragment", "quantity": 2}], "reputation": 25}'::jsonb, false, false, 'fq_conc_044', false, NULL, NULL, NULL, 'quest_concordium.json', 42)
