values ('fq_conc_044', 'Abyssal Ambush', 'hunt', 'A', 'CONCORDIUM', 'VOID_ECHO_CHASM', 'Aethel Abyssal Reavers have infiltrated the chasm. (Location: Void Echo Chasm, Officer Valen) They are the Harbinger''s eyes. Leave none standing.', '{"npc_id": "npc_concordium_officer", "name": "", "location": "VOID_ECHO_CHASM"}'::jsonb, '{"min_level": 43, "reputation_required": 2520, "required_quests": ["fq_conc_043"]}'::jsonb, '[{"type": "kill", "target": "AETHEL_ABYSSAL_REAVER", "count": 5, "description": "Defeat Abyssal Reavers in the chasm. [Aethel Abyssal Reaver]"}, {"type": "kill", "target": "VOID_REAVER", "count": 3, "description": "Clear out Void Reaver patrols."}]'::jsonb, '{"exp": 2200, "currency": 1100, "crd": 550, "rep": 750, "items": [{"item_id": "void_crystal_shard", "quantity": 2}], "reputation": 25}'::jsonb, false, false, 'fq_conc_045', false, NULL, NULL, NULL, 'quest_concordium.json', 43)
