values ('fq_conc_045', 'Corrupted Depths', 'boss', 'A', 'CONCORDIUM', 'VOID_ECHO_CHASM', 'Aethel Corrupted Behemoths guard the path deeper into the chasm. (Location: Void Echo Chasm, Officer Valen) These creatures have been twisted beyond recognition.', '{"npc_id": "npc_concordium_officer", "name": "", "location": "VOID_ECHO_CHASM"}'::jsonb, '{"min_level": 44, "reputation_required": 2580, "required_quests": ["fq_conc_044"]}'::jsonb, '[{"type": "kill", "target": "AETHEL_CORRUPTED_BEHEMOTH", "count": 3, "description": "Defeat Corrupted Behemoths in the chasm depths. [Aethel Corrupted Behemoth]"}, {"type": "collect", "target": "crystal_core", "count": 1, "description": "Collect crystal core (x1). [Item: Crystal Core]"}]'::jsonb, '{"exp": 2500, "currency": 1300, "crd": 650, "rep": 800, "items": [{"item_id": "corrupted_synapse_cluster", "quantity": 1}], "reputation": 25}'::jsonb, false, false, 'fq_conc_046', false, NULL, NULL, NULL, 'quest_concordium.json', 44)
