values ('fq_conc_046', 'Echoes of the Past', 'story', 'A', 'CONCORDIUM', 'VOID_ECHO_CHASM', 'You discover ancient Concordium logs deep in the chasm. (Location: Void Echo Chasm, Officer Valen) Recover them — they may contain the key to stopping the Harbinger.', '{"npc_id": "npc_concordium_officer", "name": "", "location": "VOID_ECHO_CHASM"}'::jsonb, '{"min_level": 45, "reputation_required": 155, "required_quests": ["fq_conc_045"]}'::jsonb, '[{"type": "collect", "target": "void_channeler_core", "count": 3, "description": "Collect void channeler core (x3). [Item: Void Channeler Core]"}, {"type": "kill", "target": "AETHEL_VOID_CHANNELER", "count": 4, "description": "Defeat Channelers protecting the log sites. [Aethel Void Channeler]"}]'::jsonb, '{"exp": 2400, "currency": 1200, "crd": 600, "rep": 780, "items": [{"item_id": "memory_fragment_chip", "quantity": 3}], "reputation": 25}'::jsonb, false, false, 'fq_conc_047', false, NULL, NULL, NULL, 'quest_concordium.json', 45)
