values ('fq_conc_047', 'Jotunn''s Gate', 'boss', 'A', 'CONCORDIUM', 'VOID_ECHO_CHASM', 'A Gigantic Jotunn guards an ancient gate within the chasm. (Location: Void Echo Chasm, Officer Valen) This creature must fall for the Concordium to proceed deeper.', '{"npc_id": "npc_concordium_officer", "name": "", "location": "VOID_ECHO_CHASM"}'::jsonb, '{"min_level": 46, "reputation_required": 2700, "required_quests": ["fq_conc_046"]}'::jsonb, '[{"type": "kill", "target": "GIGANTIC_JOTUNN", "count": 1, "description": "Defeat the Gigantic Jotunn at the chasm gate."}, {"type": "kill", "target": "VOID_REAVER", "count": 4, "description": "Clear Void Reavers from the gate area."}]'::jsonb, '{"exp": 3500, "currency": 1800, "crd": 900, "rep": 1000, "items": [{"item_id": "titan_core", "quantity": 1}, {"item_id": "con_elite_recovery_pack", "quantity": 3}], "reputation": 25}'::jsonb, false, false, 'fq_conc_048', false, NULL, NULL, NULL, 'quest_concordium.json', 46)
